    i32 SolveQuadratic(f32 a, f32 b, f32 c, f32 *first, f32 *second) {
        f64 four_ac;
        f64 b_squared;
        f32 root;
        if (a == 0.0f) {
            if (b == 0.0f) {
                return 0;
            }
            *first = *second = -c / b;
            return 1;
        }
        four_ac = 4.0 * a * c;
        b_squared = (f64)b * b;
        if (four_ac > b_squared) {
            return 0;
        }
        if (four_ac == b_squared) {
            *first = *second = -b / (a * 2.0f);
            return 1;
        }
        root = NuFsqrt(b_squared - four_ac);
        *first = (-b - root) / (a * 2.0f);
        *second = (root - b) / (a * 2.0f);
        return 1;
    }

