    DEBRISKEY *debris_keystack = 0;

    void AddDebrisEffectToStack(DEBRISKEY *key) {
        if (debris_keystack != NULL) {
            debris_keystack->next = key;
        }
        key->previous = debris_keystack;
        debris_keystack = key;
    }

    void RemoveDebrisEffectFromStack(DEBRISKEY *key) {
        if (key->next == NULL) {
            debris_keystack = key->previous;
            if (debris_keystack != NULL) {
                debris_keystack->next = NULL;
            }
        } else {
            key->next->previous = key->previous;
            if (key->previous != NULL) {
                key->previous->next = key->next;
            }
        }
        key->next = NULL;
        key->previous = NULL;
    }

    void DebrisProcessSpheres(DEBRISPARTICLE *particle, f32 time, DEBRIS_INFO *effect, DEBRISKEY *key, i32 finite) {
        if (time >= key->sphere_next_time) {
            if (key->sphere_skip_count > 0) {
                --key->sphere_skip_count;
                return;
            }
            key->process_spheres[key->sphere_index].time = time;
            key->process_spheres[key->sphere_index].position.x = key->position.x + particle->position.x;
            key->process_spheres[key->sphere_index].position.y = key->position.y + particle->position.y;
            key->process_spheres[key->sphere_index].position.z = key->position.z + particle->position.z;
            key->process_spheres[key->sphere_index].momentum = particle->momentum;
            if (++key->sphere_index >= effect->process_spheres) {
                key->sphere_index = 0;
            }
            if (finite != 0) {
                key->sphere_skip_count = key->sphere_index;
            }
            key->sphere_next_time = time + effect->particle_lifetime / (f32)effect->process_spheres;
        }
    }

    f32 debris_thinning_level = 1.0f;
    DEBRISGENERATOR gensorttab[13] = {GenDebIndex,          GenDebDummy,        GenDebDummy,         GenDebDummy,
                                      GenDebDummy,          GenDebDummy,        GenDebIndexRadial,   GenDebIndexRadialRotor,
                                      GenDebIndexSpheroid,  GenDebIndexBounceY, GenDebIndexBounceXZ, GenDebIndexImprovedRadial,
                                      GenDebIndexRadialStar};
    DEBRISMOMENTUMADJUSTER gencodetab[7] = {NULL,
                                            GenDebMomAdjFromPos,
                                            GenDebMomAdjFromPosRev,
                                            GenDebMomAdjFromSplash,
                                            GenDebMomAdjFromAshRock,
                                            GenDebMomAdjFromPosRevTree,
                                            GenDebMomAdjFromPosAll};
    i32 forced_debris_thinning = 0;
    i32 update_debris_enabled = 1;
    i32 debris_suspended = 0;

    void AddVariableShotDebrisEffectTimed5(i32 effect_index, NUVEC *position, NUVEC *momentum, NUVEC *position_delta, i32 count,
                                           f32 duration, NUMTX *emitter_orientation, NUMTX *particle_orientation, u16 render_priority,
                                           i8 timed_flags) {
        DEBRIS_INFO *effect;
        NUVEC clipped_position;

        f32 thinning;
        f32 emission_interval;
        f32 rate;
        f32 now;
        f32 end_time;
        f32 elapsed_intervals;
        f32 emission_time;
        f32 emission_epoch;
        f32 next_emission_time;
        i32 panel_time;
        i32 emission_count;
        i32 i;
        i32 j;
        i32 particle;
        i32 particle_count;
        i32 particle_key_slot;
        i32 new_key_index;
        DEBRISKEY *key;
        i32 required_particles;
        i32 required_chunks;
        i32 new_chunk_count;
        i32 total_chunk_count;
        DEBRISPARTICLE *generated;
        i32 chunk_index;
        DEBRIS_CHUNK_CONTROL *control;
        DEBRIS_CHUNK_CONTROL **stack;
        DEBRIS_PARTICLE_CHUNK *last_chunk;

        if (debris_suspended != 0 || update_debris_enabled == 0 || effect_index == -1 || effect_index == 0 ||
            effect_index >= debinf_count) {
            return;
        }
        effect = debtab[effect_index];
        if (effect == NULL || effect->disabled != 0 || count <= 0) {
            return;
        }
        if (DEBRIS_DRAW_PANEL != effect->time_group) {
            NUVEC extent;
            clipped_position.x = position->x;
            clipped_position.y = position->y;
            clipped_position.z = position->z;
            extent.x = extent.y = extent.z = 1.0f;
            if (NuCameraClipTestExtentsAxisAligned(&clipped_position, &extent, effect->clip_extent) == 0) {
                return;
            }
        }
        thinning = 0 != forced_debris_thinning ? debris_thinning_level
                                               : (effect->thinning < debris_thinning_level ? effect->thinning : debris_thinning_level);
        rate = TerrainDivideNonzeroPC((f32)count, thinning);
        emission_interval = TerrainDivideNonzeroPC(1.0f, rate);
        if (emitter_orientation == NULL) {
            emitter_orientation = &NuMtxSetIdentityTemplate;
        }
        if (particle_orientation == NULL) {
            particle_orientation = &NuMtxSetIdentityTemplate;
        }
        if (effect->time_group == DEBRIS_DRAW_PANEL) {
            now = panelglobaltime;
            panel_time = 1;
        } else {
            now = globaltime;
            panel_time = 0;
        }
        end_time = now + duration;
        emission_epoch = ((f32)(i32)TerrainDivideNonzeroPC(now, emission_interval)) * emission_interval;
        emission_time = emission_epoch + emission_interval;
        emission_count = 0;
        next_emission_time = emission_time;
        i = 0;
        while (next_emission_time <= end_time) {
            if (++i >= 100) {
                break;
            }
            ++emission_count;
            next_emission_time += emission_interval;
        }
        if (emission_count == 0) {
            return;
        }
        particle_count = emission_count * (effect->trail_count + 1);
        particle_key_slot = -1;
        key = NULL;
        for (i = 0; i < 8; ++i) {
            if (effect->particle_keys[i] != -1) {
                key = &debkeydata[effect->particle_keys[i]];
                if (effect->particle_type == DEBRIS_PARTICLE_GLASS) {
                    if (key->particle_count + particle_count <= 0x180) {
                        particle_key_slot = i;
                        break;
                    }
                } else if (key->particle_count + particle_count <= 0x400) {
                    particle_key_slot = i;
                    break;
                }
            } else if (freedebkeyptr < maxdebkeys) {
                new_key_index = DebAlloc();
                effect->particle_keys[i] = (i16)new_key_index;
                key = &debkeydata[(i16)new_key_index];
                key->effect_index = (i16)effect_index;
                key->finite_count = 0;
                key->generator = gensorttab[effect->generator_type];
                key->momentum_adjuster = gencodetab[effect->momentum_adjustment_type];
                key->effect_orientation = *particle_orientation;
                key->effect_orientation.m30 = 0.0f;
                key->effect_orientation.m31 = 0.0f;
                key->effect_orientation.m32 = 0.0f;
                DebrisEmitterPos(effect->particle_keys[i], 0.0f, 0.0f, 0.0f);
                key->render_priority = render_priority;
                key->timed_flags = timed_flags;
                particle_key_slot = i;
                break;
            }
        }
        if (key == NULL) {
            return;
        }
        required_particles = particle_count + key->particle_count;
        if (effect->particle_type == DEBRIS_PARTICLE_GLASS) {
            if (required_particles > key->allocated_chunk_count * 12) {
                if (key->allocated_chunk_count < 0) {
                    key->allocated_chunk_count = 0;
                }
                required_chunks = (required_particles + 12 - 1) / 12;
                new_chunk_count = required_chunks - key->allocated_chunk_count;
                if (freedebchkptrg + new_chunk_count >= debrischunksglass || required_chunks > 32) {
                    return;
                }
                for (i = 0; i < new_chunk_count; ++i) {
                    key->particle_chunks[key->allocated_chunk_count] = freedebchunksglass[freedebchkptrg++];
                    for (particle = 0; particle < 12; ++particle) {
                        key->particle_chunks[key->allocated_chunk_count]->particles[particle].start_time = 0.0f;
                        key->particle_chunks[key->allocated_chunk_count]->particles[particle].inverse_lifetime = 32768.0f;
                    }
                    ++key->allocated_chunk_count;
                }
                key->allocated_chunk_count = (i16)required_chunks;
                LinkDmaParticalSets(key->particle_chunks, required_chunks);
                if (required_chunks == new_chunk_count) {
                    total_chunk_count = debrischunks + debrischunksglass;
                    for (j = 0; j < total_chunk_count; ++j) {
                        if (NULL == ParticleChunkToRender[j].particle_chunk) {
                            ParticleChunkToRender[j].particle_chunk = key->particle_chunks[0];
                            ParticleChunkToRender[j].effect = effect;
                            ParticleChunkToRender[j].key = key;
                            ParticleChunkToRender[j].render_priority = render_priority;
                            AddChunkToRenderStack(&ParticleChunkToRender[j], &ParticleChunkRenderStack[effect->time_group]);
                            break;
                        }
                    }
                }
            }
        } else {
            if (required_particles > key->allocated_chunk_count * 32) {
                if (key->allocated_chunk_count < 0) {
                    key->allocated_chunk_count = 0;
                }
                required_chunks = (required_particles + 32 - 1) / 32;
                new_chunk_count = required_chunks - key->allocated_chunk_count;
                if (freedebchkptr + new_chunk_count >= debrischunks || required_chunks > 32) {
                    return;
                }
                for (i = 0; i < new_chunk_count; ++i) {
                    key->particle_chunks[key->allocated_chunk_count] = freedebchunks[freedebchkptr++];
                    for (particle = 0; particle < 32; ++particle) {
                        key->particle_chunks[key->allocated_chunk_count]->particles[particle].start_time = 0.0f;
                        key->particle_chunks[key->allocated_chunk_count]->particles[particle].inverse_lifetime = 32768.0f;
                    }
                    ++key->allocated_chunk_count;
                }
                key->allocated_chunk_count = (i16)required_chunks;
                LinkDmaParticalSets(key->particle_chunks, required_chunks);
                if (required_chunks == new_chunk_count) {
                    total_chunk_count = debrischunks + debrischunksglass;
                    for (j = 0; j < total_chunk_count; ++j) {
                        if (NULL == ParticleChunkToRender[j].particle_chunk) {
                            ParticleChunkToRender[j].particle_chunk = key->particle_chunks[0];
                            ParticleChunkToRender[j].effect = effect;
                            ParticleChunkToRender[j].key = key;
                            ParticleChunkToRender[j].render_priority = render_priority;
                            AddChunkToRenderStack(&ParticleChunkToRender[j], &ParticleChunkRenderStack[effect->time_group]);
                            break;
                        }
                    }
                }
            }
        }
        key->particle_count += (i16)particle_count;
        if (momentum != NULL) {
            key->momentum.x = momentum->x;
            key->momentum.y = momentum->y;
            key->momentum.z = momentum->z;
        } else {
            key->momentum.x = 0.0f;
            key->momentum.y = 0.0f;
            key->momentum.z = 0.0f;
        }
        DebrisEmitterOrientationMtx(effect->particle_keys[particle_key_slot], emitter_orientation);
        key->emission_epoch = emission_epoch;
        i = 0;
        while (emission_time <= end_time) {
            if (++i >= 100) {
                break;
            }
            if (position_delta != NULL) {
                NuVecAddScale(&key->emission_position, position, position_delta, emission_time - end_time);
            } else {
                key->emission_position.x = position->x;
                key->emission_position.y = position->y;
                key->emission_position.z = position->z;
            }
            key->emission_time = emission_time;
            generated = key->generator(key, effect, emission_time);
            if (effect->process_spheres != 0 && i == 1 && generated != NULL) {
                DebrisProcessSpheres(generated, emission_time, effect, key, 1);
            }
            emission_time = emission_interval + key->emission_epoch;
        }
        DebrisGetControlStackLock();
        // MATCH-EXCEPTION: the original tests the 16-bit counts once before entering the loop.
        if (key->controlled_chunk_count < key->allocated_chunk_count) {
            for (chunk_index = key->controlled_chunk_count; chunk_index < key->allocated_chunk_count; ++chunk_index) {
                if (freechunkcontrolsptr < (debrischunks + debrischunksglass) * 2) {
                    freechunkcontrols[freechunkcontrolsptr]->particle_chunk = key->particle_chunks[chunk_index];
                    freechunkcontrols[freechunkcontrolsptr]->expiry_time =
                        now + effect->particle_lifetime + (f32)effect->trail_count * effect->trail_time;
                    freechunkcontrols[freechunkcontrolsptr]->active = 1;
                    freechunkcontrols[freechunkcontrolsptr]->owner = key;
                    AddChunkControlToStack(freechunkcontrols[freechunkcontrolsptr], &debris_chunk_control_stack[panel_time]);
                    ++freechunkcontrolsptr;
                    ++key->controlled_chunk_count;
                }
            }
        }
        if (key->allocated_chunk_count == key->controlled_chunk_count) {
            last_chunk = key->particle_chunks[key->controlled_chunk_count - 1];
            stack = &debris_chunk_control_stack[panel_time];
            for (control = *stack; control != NULL; control = control->next) {
                if (control->particle_chunk == last_chunk) {
                    RemoveChunkControlFromStack(control, stack);
                    control->expiry_time = now + effect->particle_lifetime + (f32)effect->trail_count * effect->trail_time;
                    AddChunkControlToStack(control, stack);
                    break;
                }
            }
        }
        key->previous_particle_count = key->particle_count;
        key->previous_allocated_chunk_count = key->allocated_chunk_count;
        debris_control_stack_lock = 0;
    }

    // PC debris timing uses a single-precision 1/60-second step.
    f32 debris_time_increment = 1.0f / 60.0f;

    void AddVariableShotDebrisEffectMtx4(i32 effect, NUVEC *position, NUVEC *momentum, i32 count, NUMTX *emitter_orientation,
                                         NUMTX *particle_orientation, u16 priority, i8 flags) {
        AddVariableShotDebrisEffectTimed5(effect, position, momentum, NULL, count * 30, debris_time_increment, emitter_orientation,
                                          particle_orientation, priority, flags);
    }

    void AddVariableShotDebrisEffectTimed3(i32 effect, NUVEC *position, NUVEC *momentum, i32 count, f32 time, NUMTX *emitter_orientation,
                                           NUMTX *particle_orientation) {
        u16 priority;
        if (effect < 0 || debtab[effect] == NULL) {
            return;
        }
        switch (debtab[effect]->particle_type) {
            case DEBRIS_PARTICLE_MODULATIVE:
                priority = 40000;
                break;
            case DEBRIS_PARTICLE_SUBTRACTIVE:
                priority = 30000;
                break;
            case DEBRIS_PARTICLE_GLASS:
                priority = 10000;
                break;
            default:
                priority = 20000;
                break;
        }
        AddVariableShotDebrisEffectTimed5(effect, position, momentum, NULL, count, time, emitter_orientation, particle_orientation,
                                          priority, 0);
    }

    void AddVariableShotDebrisEffectMtx3(i32 effect, NUVEC *position, NUVEC *momentum, i32 count, NUMTX *emitter_orientation,
                                         NUMTX *particle_orientation) {
        u16 priority;
        if (effect < 0 || debtab[effect] == NULL) {
            return;
        }
        switch (debtab[effect]->particle_type) {
            case DEBRIS_PARTICLE_MODULATIVE:
                priority = 40000;
                break;
            case DEBRIS_PARTICLE_SUBTRACTIVE:
                priority = 30000;
                break;
            case DEBRIS_PARTICLE_GLASS:
                priority = 10000;
                break;
            default:
                priority = 20000;
                break;
        }
        AddVariableShotDebrisEffectTimed5(effect, position, momentum, NULL, count * 30, debris_time_increment, emitter_orientation,
                                          particle_orientation, priority, 0);
    }

    i32 debris_render_group = 0;

    void DebrisSetRenderGroup(i32 group) {
        debris_render_group = group;
    }

    void DebrisDrawCalculateClipBoxes(DEBRIS_INFO *effect, DEBRISKEY *key) {
        NUMTX matrix;
        f32 padding;
        f32 radius;
        NUVEC extent;
        NUVEC minimum;
        DebrisMtxCopyPrivate(&matrix, &key->effect_orientation);
        NuMtxTranslate(&matrix, &key->position);
        extent.x = (DebrisFabs(effect->emitter_velocity.x) * (effect->emission_period_random + effect->emission_period) +
                    effect->momentum_random_x * effect->particle_lifetime) +
                   effect->emitter_random_extent.x;
        extent.y = (DebrisFabs(effect->emitter_velocity.y) * (effect->emission_period_random + effect->emission_period) +
                    (DebrisFabs(effect->momentum_base) + effect->rotor_speed_x) * effect->particle_lifetime) +
                   effect->emitter_random_extent.y;
        extent.z = (DebrisFabs(effect->emitter_velocity.z) * (effect->emission_period_random + effect->emission_period) +
                    effect->rotor_speed_y * effect->particle_lifetime) +
                   effect->emitter_random_extent.z;
        NuVecMtxRotate(&extent, &extent, &key->emitter_orientation);
        if (extent.x < 0.0f) {
            extent.x = -extent.x;
        }
        if (extent.y < 0.0f) {
            extent.y = -extent.y;
        }
        if (extent.z < 0.0f) {
            extent.z = -extent.z;
        }
        padding = (f32)((f64)0.0001f * effect->max_size);
        /* Rounds after each padding pass. */
        extent.x += padding;
        extent.y += padding;
        extent.z += padding;
        extent.x = (f32)(extent.x + (f64)0.2f);
        extent.y = (f32)(extent.y + (f64)0.2f);
        extent.z = (f32)(extent.z + (f64)0.2f);
        minimum.x = -extent.x;
        minimum.y = -extent.y;
        minimum.z = -extent.z;
        if (effect->gravity > 0.0f) {
            extent.y += (effect->gravity * effect->particle_lifetime) * effect->particle_lifetime;
        } else if (effect->gravity < 0.0f) {
            minimum.y += (effect->gravity * effect->particle_lifetime) * effect->particle_lifetime;
        }
        radius = MAX(MAX(extent.x, extent.z), MAX(extent.y, -minimum.y));
        key->clip_radius = radius;
        key->clip_min = minimum;
        key->clip_max = extent;
        DebrisMtxCopyPrivate(&key->clip_matrix, &matrix);
    }

    void DebrisProcessControlChunks(i32 panel_time) {
        const f32 now = panel_time == 1 ? panelglobaltime : globaltime;
        DEBRIS_CHUNK_CONTROL *control = debris_chunk_control_stack[panel_time];
        i32 i;

        DebrisGetControlStackLock();
        for (; control != NULL && control->expiry_time <= now; control = debris_chunk_control_stack[panel_time]) {
            debris_chunk_control_stack[panel_time] = control->next;
            control->next = NULL;

            if (control->active == 5) {
                DEBRIS_INFO *effect = debtab[control->effect_index];
                DEBRISPARTICLE *particle = &control->particle_chunk->particles[control->particle_index];
                f32 old_term = particle->momentum.y * control->collision_time;
                f32 bounce = particle->momentum.y + effect->gravity * control->collision_time * 2.0f;
                f32 new_term;
                f32 height;
                f32 first;
                f32 second;
                bounce = -control->restitution * bounce;
                particle->momentum.y = bounce - effect->gravity * control->collision_time * 2.0f;
                new_term = particle->momentum.y * control->collision_time;
                height = particle->position.y - (new_term - old_term);
                particle->position.y = height;
                height -= control->collision_plane;
                if (SolveQuadratic(effect->gravity, particle->momentum.y, height, &first, &second) != 0) {
                    if (MAX(first, second) < effect->particle_lifetime) {
                        const f32 interval = MAX(first, second) - control->collision_time;
                        control->collision_time = MAX(first, second);
                        if (!(interval <= 0.02f)) {
                            control->expiry_time += interval;
                            AddChunkControlToStack(control, &debris_chunk_control_stack[panel_time]);
                            continue;
                        }
                    }
                }
                freechunkcontrols[--freechunkcontrolsptr] = control;
                control->particle_chunk = NULL;
                continue;
            }

            if (control->active == 6) {
                NUVEC normal = {1.0f, 0.0f, 0.0f};
                DEBRISPARTICLE *particle = &control->particle_chunk->particles[control->particle_index];
                f32 value;
                f32 old_x;
                f32 old_z;
                f32 new_z;
                NuVecRotateY(&normal, &normal, control->rotation_y);
                value = particle->momentum.x * normal.x + particle->momentum.z * normal.z;
                value = -(value * (control->restitution + 1.0));
                old_x = particle->momentum.x * control->collision_time;
                old_z = particle->momentum.z * control->collision_time;
                particle->momentum.x = value * normal.x + particle->momentum.x;
                value = value * normal.z + particle->momentum.z;
                particle->momentum.z = value;
                new_z = value * control->collision_time;
                value = particle->momentum.x * control->collision_time;
                particle->position.x = particle->position.x - (value - old_x);
                particle->position.z = particle->position.z - (new_z - old_z);
                freechunkcontrols[--freechunkcontrolsptr] = control;
                control->particle_chunk = NULL;
                continue;
            }

            if (control->active == 3) {
                --freedebchkptr;
                freedebchunks[freedebchkptr] = control->particle_chunk;
                for (i = 0; i < 32; ++i) {
                    control->particle_chunk->particles[i].start_time = 10000000000.0f;
                    control->particle_chunk->particles[i].inverse_lifetime = 128.0f;
                }
                freechunkcontrols[--freechunkcontrolsptr] = control;
                control->particle_chunk = NULL;
                continue;
            }

            if (control->active == 8) {
                --freedebchkptrg;
                freedebchunksglass[freedebchkptrg] = control->particle_chunk;
                for (i = 0; i < 12; ++i) {
                    control->particle_chunk->particles[i].start_time = 10000000000.0f;
                    control->particle_chunk->particles[i].inverse_lifetime = 128.0f;
                }
                freechunkcontrols[--freechunkcontrolsptr] = control;
                control->particle_chunk = NULL;
                continue;
            }

            if (control->active == 2) {
                LinkDmaParticalSets(&control->particle_chunk, 1);
                control->active = 3;
                control->expiry_time += 0.1f;
                AddChunkControlToStack(control, &debris_chunk_control_stack[panel_time]);
                continue;
            }

            if (control->active == 9) {
                LinkDmaParticalSets(&control->particle_chunk, 1);
                control->active = 8;
                control->expiry_time += 0.1f;
                AddChunkControlToStack(control, &debris_chunk_control_stack[panel_time]);
                continue;
            }

            if (control->active == 0 || control->active == 7) {
                for (i = 0; i < debrischunks + debrischunksglass; ++i) {
                    if (ParticleChunkToRender[i].particle_chunk == control->particle_chunk) {
                        RemoveChunkFromRenderStack(&ParticleChunkToRender[i],
                                                   &ParticleChunkRenderStack[ParticleChunkToRender[i].effect->time_group]);
                        ParticleChunkToRender[i].particle_chunk = NULL;
                        ParticleChunkToRender[i].effect = NULL;
                        ParticleChunkToRender[i].key = NULL;
                        break;
                    }
                }
                control->expiry_time += 0.1f;
                if (control->active == 0) {
                    control->active = 2;
                } else if (control->active == 7) {
                    control->active = 9;
                }
                AddChunkControlToStack(control, &debris_chunk_control_stack[panel_time]);
                continue;
            }

            if (control->active == 1) {
                DEBRIS_INFO *effect = debtab[control->owner->effect_index];
                i32 chunk_index = 0;
                for (i = 0; i < control->owner->allocated_chunk_count; ++i) {
                    if (control->owner->particle_chunks[i] == control->particle_chunk) {
                        chunk_index = i;
                        break;
                    }
                }
                for (i = chunk_index; i < control->owner->allocated_chunk_count - 1; ++i) {
                    control->owner->particle_chunks[i] = control->owner->particle_chunks[i + 1];
                }
                control->owner->particle_chunks[control->owner->allocated_chunk_count - 1] = NULL;
                --control->owner->allocated_chunk_count;
                --control->owner->previous_allocated_chunk_count;
                --control->owner->controlled_chunk_count;

                if (control->owner->allocated_chunk_count > 0) {
                    if (effect->particle_type == DEBRIS_PARTICLE_GLASS) {
                        control->owner->particle_count -= 12;
                        control->owner->previous_particle_count -= 12;
                        if (control->owner->particle_cursor > (chunk_index + 1) * 12) {
                            control->owner->particle_cursor -= 12;
                        }
                    } else {
                        control->owner->particle_count -= 32;
                        control->owner->previous_particle_count -= 32;
                        if (control->owner->particle_cursor > (chunk_index + 1) * 32) {
                            control->owner->particle_cursor -= 32;
                        }
                    }
                } else {
                    control->owner->particle_count = 0;
                    control->owner->previous_particle_count = 0;
                }
                if (control->owner->allocated_chunk_count > 0) {
                    LinkDmaParticalSets(control->owner->particle_chunks, control->owner->allocated_chunk_count);
                } else {
                    for (i = 0; i < 8; ++i) {
                        if (effect->particle_keys[i] != -1 && &debkeydata[effect->particle_keys[i]] == control->owner) {
                            control->owner->effect_index = 0;
                            control->owner->allocation_index = -1;
                            --freedebkeyptr;
                            freedebkeys[freedebkeyptr] = effect->particle_keys[i];
                            effect->particle_keys[i] = -1;
                        }
                    }
                    control->owner->particle_chunks[0] = NULL;
                }

                if (chunk_index == 0) {
                    for (i = 0; i < debrischunks + debrischunksglass; ++i) {
                        if (ParticleChunkToRender[i].particle_chunk == control->particle_chunk) {
                            ParticleChunkToRender[i].particle_chunk = control->owner->particle_chunks[0];
                            if (control->owner->allocated_chunk_count == 0) {
                                RemoveChunkFromRenderStack(&ParticleChunkToRender[i], &ParticleChunkRenderStack[effect->time_group]);
                                ParticleChunkToRender[i].effect = NULL;
                                ParticleChunkToRender[i].key = NULL;
                            }
                            break;
                        }
                    }
                }

                control->expiry_time += 0.1f;
                control->active = effect->particle_type == DEBRIS_PARTICLE_GLASS ? 9 : 2;
                AddChunkControlToStack(control, &debris_chunk_control_stack[panel_time]);
                continue;
            }
        }
        DebrisReleaseControlStackLock();
    }

    void DebrisSetTimeIncrement(f32 increment) {
        debris_time_increment = increment;
    }

    f32 debris_render_global_time = 0;
    f32 debris_render_panel_time = 0;

    void DebrisTimeSlip(i32 group) {
        DEBRIS_CHUNK_CONTROL *control;
        i32 i;
        i32 chunk_index;
        i32 particle_index;
        i32 glass;
        if (group == 0) {
            globaltime = debris_render_global_time;
            for (control = debris_chunk_control_stack[0]; control != NULL; control = control->next) {
                control->expiry_time -= 800.0;
            }
        } else if (group == 1) {
            panelglobaltime = debris_render_panel_time;
            for (control = debris_chunk_control_stack[1]; control != NULL; control = control->next) {
                control->expiry_time -= 800.0;
            }
        }
        for (i = 0; i < maxdebkeys; ++i) {
            DEBRIS_INFO *effect = debtab[debkeydata[i].effect_index];
            if ((effect->time_group == DEBRIS_DRAW_PANEL && group == 1) || (effect->time_group != DEBRIS_DRAW_PANEL && group == 0)) {
                glass = effect->particle_type == DEBRIS_PARTICLE_GLASS;
                debkeydata[i].last_update_time -= 800.0;
                debkeydata[i].emission_epoch -= 800.0;
                debkeydata[i].emission_time -= 800.0;
                debkeydata[i].previous_emission_time -= 800.0;
                debkeydata[i].emission_end_time -= 800.0;
                for (chunk_index = 0; chunk_index < 32; ++chunk_index) {
                    if (debkeydata[i].particle_chunks[chunk_index] != NULL) {
                        if (glass) {
                            for (particle_index = 0; particle_index < 12; ++particle_index) {
                                debkeydata[i].particle_chunks[chunk_index]->particles[particle_index].start_time -= 800.0;
                            }
                        } else {
                            for (particle_index = 0; particle_index < 32; ++particle_index) {
                                debkeydata[i].particle_chunks[chunk_index]->particles[particle_index].start_time -= 800.0;
                            }
                        }
                    }
                }
            }
        }
        for (i = 1; i < debinf_count; ++i) {
            if (debtab[i] != NULL && ((debtab[i]->time_group == DEBRIS_DRAW_PANEL && group == 1) ||
                                      (debtab[i]->time_group != DEBRIS_DRAW_PANEL && group == 0))) {
                debtab[i]->last_render_time -= 800.0;
                if (debtab[i]->native_data != NULL) {
                    debtab[i]->native_data->last_render_time -= 800.0;
                }
            }
        }
    }

    void DebrisProcessTimeSlip(void) {
        if (debris_render_global_time < globaltime - 1.0) {
            DebrisTimeSlip(0);
        } else if (globaltime > 900.0) {
            debris_render_global_time -= 800.0;
        }
        if (debris_render_panel_time < panelglobaltime - 1.0) {
            DebrisTimeSlip(1);
        } else if (panelglobaltime > 900.0) {
            debris_render_panel_time -= 800.0;
        }
    }

    void DebrisFreeOldestDmaDebTypeTable(void) {
        i32 i;
        i32 oldest = 0;
        f32 oldest_age = 0.0f;
        f32 age;
        for (i = 1; i < debinf_count; ++i) {
            if (debtab[i] != NULL && debtab[i]->native_data != NULL) {
                age = (debtab[i]->time_group == DEBRIS_DRAW_PANEL ? panelglobaltime : globaltime) - debtab[i]->last_render_time;
                if (age > oldest_age) {
                    oldest_age = age;
                    oldest = i;
                }
            }
        }
        if (oldest != 0) {
            DmaDebTypes[--freeDmaDebType] = debtab[oldest]->native_data;
            debtab[oldest]->native_data = NULL;
        }
    }

    i32 globalframes = 0;

    void DebrisResetGlobalTime(void) {
        globalframes = 0;
        panelglobaltime = 0.0f;
        debris_render_panel_time = 0.0f;
        globaltime = 0.0f;
        debris_render_global_time = 0.0f;
    }

    void DebrisReScale(i32 effect_index, f32 scale) {
        DEBRIS_INFO *effect;
        i32 i;
        u8 generator;
        if (effect_index < 0 || effect_index >= debinf_count) {
            return;
        }
        effect = debtab[effect_index];
        if (effect == NULL) {
            return;
        }
        for (i = 0; i < 8; ++i) {
            effect->width_keys[i].value *= scale;
            effect->height_keys[i].value *= scale;
        }
        effect->min_size *= scale;
        effect->max_size *= scale;
        effect->momentum_base *= scale;
        effect->gravity *= scale;
        generator = (u8)effect->generator_type;
        if (generator == DEBRIS_GENERATOR_NORMAL || generator == DEBRIS_GENERATOR_SPHEROID || generator == DEBRIS_GENERATOR_BOUNCE_Y ||
            generator == DEBRIS_GENERATOR_BOUNCE_XZ) {
            effect->emitter_random_extent.x *= scale;
            effect->emitter_random_extent.y *= scale;
            effect->emitter_random_extent.z *= scale;
            effect->momentum_random_x *= scale;
            effect->rotor_speed_x *= scale;
            effect->rotor_speed_y *= scale;
        } else if (generator == DEBRIS_GENERATOR_RADIAL || generator == DEBRIS_GENERATOR_RADIAL_ROTOR ||
                   generator == DEBRIS_GENERATOR_IMPROVED_RADIAL || generator == DEBRIS_GENERATOR_STAR_RADIAL) {
            effect->emitter_random_extent.x *= scale;
            effect->momentum_random_x *= scale;
        }
        effect->jib_x_amplitude *= scale;
        effect->jib_y_amplitude *= scale;
        GenericDebinfoDmaTypeUpdate(effect);
    }

    DEBRIS_INFO *DebrisGetInfo(i32 index) {
        if (index >= 0 && index < debinf_count && debtab[index] != NULL) {
            return debtab[index];
        }
        return NULL;
    }

    f32 DebrisGetCycleTime(i32 index) {
        if (index >= 0 && index < debinf_count && debtab[index] != NULL) {
            DEBRIS_INFO *info = debtab[index];
            return info->emission_period_random + info->emission_period + info->emission_pause + info->emission_pause_random;
        }
        return 0.0f;
    }

    i32 edpp_page_used[8] = {0};

    i32 LookupDebrisEffectPageIgnore(char *name, i8 page, i32 ignore) {
        i32 i;

        if (name == NULL) {
            return -1;
        }

        if ((u8)page <= 7 && edpp_page_used[page] != 0) {
            for (i = 1; i < debinf_count; ++i) {
                if (i != ignore && debtab[i] != NULL && debtab[i]->page == page && NuStrICmp(debtab[i]->name, name) == 0) {
                    return i;
                }
            }
        }

        for (i = 1; i < debinf_count; ++i) {
            if (i != ignore && debtab[i] != NULL &&
                ((debtab[i]->page == 0 && edpp_page_used[0] != 0) || (debtab[i]->page == 1 && edpp_page_used[1] != 0)) &&
                NuStrICmp(debtab[i]->name, name) == 0) {
                return i;
            }
        }

        for (i = 1; i < debinf_count; ++i) {
            if (i != ignore && debtab[i] != NULL && edpp_page_used[debtab[i]->page] != 0 && NuStrICmp(debtab[i]->name, name) == 0) {
                return i;
            }
        }
        return -1;
    }

    i32 LookupDebrisEffectPage(char *name, i8 page) {
        return LookupDebrisEffectPageIgnore(name, page, 0);
    }

    i32 LookupDebrisEffectPageOnly(char *name, i8 page) {
        i32 i;

        if (name == NULL) {
            return -1;
        }

        if ((u8)page <= 7 && edpp_page_used[page] != 0) {
            for (i = 1; i < debinf_count; ++i) {
                if (debtab[i] != NULL && debtab[i]->page == page && NuStrICmp(debtab[i]->name, name) == 0) {
                    return i;
                }
            }
        }

        for (i = 1; i < debinf_count; ++i) {
            if (debtab[i] != NULL &&
                ((debtab[i]->page == 0 && edpp_page_used[0] != 0) || (debtab[i]->page == 1 && edpp_page_used[1] != 0)) &&
                NuStrICmp(debtab[i]->name, name) == 0) {
                return i;
            }
        }
        return -1;
    }

