    i32 DebrisFindAllOfType(i32 effect_index, NUVEC *positions, i32 *handles, i32 capacity, i32 skip, i32 active_only) {
        i32 count = 0;
        i32 i;
        for (i = 0; i < maxdebkeys; ++i) {
            if (debkeydata[i].effect_index == effect_index && (active_only == 0 || debkeydata[i].allocated_chunk_count != 0)) {
                if (count - skip >= 0 && count - skip < capacity) {
                    if (positions != NULL) {
                        positions[count - skip].x = debkeydata[i].position.x;
                        positions[count - skip].y = debkeydata[i].position.y;
                        positions[count - skip].z = debkeydata[i].position.z;
                    }
                    if (handles != NULL) {
                        handles[count - skip] = i;
                    }
                }
                ++count;
            }
        }
        return count - skip;
    }

    i32 DebrisGetRingProperties(i32 handle, NUVEC *origin, NUVEC *direction, f32 *radius) {
        DEBRIS_INFO *effect = debtab[debkeydata[handle].effect_index];
        DEBRISKEY *key = &debkeydata[handle];
        NUVEC axis;
        if (effect == NULL) {
            return 0;
        }
        origin->x = key->position.x;
        origin->y = key->position.y;
        origin->z = key->position.z;
        if (effect->generator_type == DEBRIS_GENERATOR_IMPROVED_RADIAL) {
            axis.x = 0.0f;
            axis.y = 1.0f;
            axis.z = 0.0f;
        } else {
            axis.x = 0.0f;
            axis.y = 0.0f;
            axis.z = 1.0f;
        }
        NuVecMtxTransform(&axis, &axis, &key->emitter_orientation);
        direction->x = axis.x;
        direction->y = axis.y;
        direction->z = axis.z;
        if (effect->generator_type != DEBRIS_GENERATOR_RADIAL && effect->generator_type != DEBRIS_GENERATOR_RADIAL_ROTOR &&
            effect->generator_type != DEBRIS_GENERATOR_IMPROVED_RADIAL) {
            *radius = 0.0f;
            return 0;
        }
        *radius = effect->emitter_random_extent.x;
        return 1;
    }

    i32 DebrisGetConeProperties(i32 handle, NUVEC *origin, NUVEC *end, f32 *start_radius, f32 *end_radius, NUVEC *direction, f32 *length,
                                f32 *speed) {
        DEBRIS_INFO *effect = debtab[debkeydata[handle].effect_index];
        DEBRISKEY *key = &debkeydata[handle];
        NUVEC axis;
        f32 cone_length;
        if (effect == NULL) {
            return 0;
        }
        origin->x = key->position.x;
        origin->y = key->position.y;
        origin->z = key->position.z;
        if (effect->generator_type != DEBRIS_GENERATOR_SPHEROID) {
            end->x = end->y = end->z = 0.0f;
            *direction = *end;
            *start_radius = *end_radius = *length = *speed = 0.0f;
            return 0;
        }
        axis.x = 0.0f;
        axis.y = 1.0f;
        axis.z = 0.0f;
        NuVecMtxTransform(&axis, &axis, &key->emitter_orientation);
        direction->x = axis.x;
        direction->y = axis.y;
        direction->z = axis.z;
        *speed = effect->momentum_base;
        cone_length = effect->momentum_base * effect->particle_lifetime;
        *length = cone_length;
        end->x = cone_length * direction->x + origin->x;
        end->y = direction->y * *length + origin->y;
        end->z = *length * direction->z + origin->z;
        *start_radius = (effect->emitter_random_extent.z + effect->emitter_random_extent.x) * 0.5;
        *end_radius = (effect->rotor_speed_y + effect->momentum_random_x) / (f64)2.8f * effect->particle_lifetime + *start_radius;
        return 1;
    }

    NUVEC debris_collide_pt = {0};

    i32 DebrisSingleTorusCollisionCheckScaleYFlag(i32 key_index, NUVEC *position, f32 radius, f32 y_scale, u8 flags) {
        DEBRIS_INFO *effect;
        DEBRIS_INFO *collision;
        f32 age;
        f32 time;
        f32 ring_radius;
        f32 horizontal_radius;
        f32 vertical_radius;
        f32 dx;
        f32 dy;
        f32 dz;
        if (debkeydata[key_index].effect_index == 0 || debkeydata[key_index].effect_index == -1) {
            return 0;
        }
        effect = debtab[debkeydata[key_index].effect_index];
        if (effect == NULL || (effect->collision_flags & flags) == 0) {
            return 0;
        }
        collision = effect;
        if (collision->torus_lifetime == 0.0f) {
            return 0;
        }
        ring_radius = 0.0f;
        horizontal_radius = 0.0f;
        vertical_radius = 0.0f;
        age = globaltime > debkeydata[key_index].emission_time ? globaltime - debkeydata[key_index].emission_time
                                                               : globaltime - debkeydata[key_index].previous_emission_time;
        if (!(age > 0.0f && age < collision->torus_lifetime)) {
            return 0;
        }
        time = age / collision->torus_lifetime;
        {
            i32 segment;
            f32 numerator;
            f32 denominator;
            for (segment = 0; segment < 7; ++segment) {
                if (time >= collision->torus_keys1[segment].time && time <= collision->torus_keys1[segment + 1].time) {
                    numerator = time - collision->torus_keys1[segment].time;
                    denominator = collision->torus_keys1[segment + 1].time - collision->torus_keys1[segment].time;
                    ring_radius =
                        collision->torus_keys1[segment].value +
                        (numerator / denominator) * (collision->torus_keys1[segment + 1].value - collision->torus_keys1[segment].value);
                    break;
                }
            }
        }
        {
            i32 segment;
            f32 numerator;
            f32 denominator;
            for (segment = 0; segment < 7; ++segment) {
                if (time >= collision->torus_keys2[segment].time && time <= collision->torus_keys2[segment + 1].time) {
                    numerator = time - collision->torus_keys2[segment].time;
                    denominator = collision->torus_keys2[segment + 1].time - collision->torus_keys2[segment].time;
                    horizontal_radius =
                        collision->torus_keys2[segment].value +
                        (numerator / denominator) * (collision->torus_keys2[segment + 1].value - collision->torus_keys2[segment].value);
                    break;
                }
            }
        }
        {
            i32 segment;
            f32 numerator;
            f32 denominator;
            for (segment = 0; segment < 7; ++segment) {
                if (time >= collision->torus_keys3[segment].time && time <= collision->torus_keys3[segment + 1].time) {
                    numerator = time - collision->torus_keys3[segment].time;
                    denominator = collision->torus_keys3[segment + 1].time - collision->torus_keys3[segment].time;
                    vertical_radius =
                        collision->torus_keys3[segment].value +
                        (numerator / denominator) * (collision->torus_keys3[segment + 1].value - collision->torus_keys3[segment].value);
                    break;
                }
            }
        }
        ring_radius *= collision->torus_radius1;
        horizontal_radius *= collision->torus_radius2;
        vertical_radius *= collision->torus_radius2;
        debris_collide_pt.x = position->x - debkeydata[key_index].position.x;
        debris_collide_pt.y = 0.0f;
        debris_collide_pt.z = position->z - debkeydata[key_index].position.z;
        NuVecNorm(&debris_collide_pt, &debris_collide_pt);
        NuVecScale(&debris_collide_pt, &debris_collide_pt, ring_radius);
        debris_collide_pt.x += debkeydata[key_index].position.x;
        debris_collide_pt.y += debkeydata[key_index].position.y;
        debris_collide_pt.z += debkeydata[key_index].position.z;
        dx = position->x - debris_collide_pt.x;
        dy = position->y - debris_collide_pt.y;
        dz = position->z - debris_collide_pt.z;
        if (y_scale != 1.0f || horizontal_radius != vertical_radius) {
            dy *= (radius + horizontal_radius) / (radius * y_scale + vertical_radius);
        }
        return (dy * dy) + (dx * dx) + dz * dz < (radius + horizontal_radius) * (radius + horizontal_radius);
    }

    i32 numtoruscolldata = 0;
    DEBRIS_COLLISION_ENTRY *toruscolldata = 0;

    i32 DebrisTorusCollisionCheckScaleYFlag(NUVEC *position, f32 radius, f32 y_scale, u8 flags) {
        i32 i;
        for (i = 0; i < numtoruscolldata; ++i) {
            if ((toruscolldata[i].flags & flags) != 0 &&
                DebrisSingleTorusCollisionCheckScaleYFlag(toruscolldata[i].key_index, position, radius, y_scale, flags) != 0) {
                return toruscolldata[i].key_index;
            }
        }
        return -1;
    }

    i32 DebrisTorusCollisionCheckScaleY(NUVEC *p, f32 r, f32 y) {
        return DebrisTorusCollisionCheckScaleYFlag(p, r, y, 3);
    }

    i32 DebrisTorusCollisionCheckFlag(NUVEC *position, f32 radius, u8 flags) {
        return DebrisTorusCollisionCheckScaleYFlag(position, radius, 1.0f, flags);
    }

    i32 DebrisTorusCollisionCheckDefault(NUVEC *position, f32 radius) {
        return DebrisTorusCollisionCheckScaleYFlag(position, radius, 1.0f, 3);
    }

    i32 DebrisSingleCollisionCheckScaleYFlag(i32 key_index, NUVEC *position, f32 radius, f32 y_scale, u8 flags) {
        DEBRIS_INFO *effect;
        DEBRIS_INFO *collision;
        i32 i;
        if (debkeydata[key_index].effect_index != 0 && debkeydata[key_index].effect_index != -1) {
            effect = debtab[debkeydata[key_index].effect_index];
            if (effect != NULL && (effect->collision_flags & flags) != 0 && effect->process_spheres != 0) {
                collision = effect;
                for (i = 0; i < effect->process_spheres; ++i) {
                    DEBRIS_PROCESS_SPHERE *sphere = &debkeydata[key_index].process_spheres[i];
                    f32 age = globaltime - sphere->time;
                    f32 time;
                    f32 effect_radius;
                    f32 dx;
                    f32 dy;
                    f32 dz;
                    if (!(age >= 0.0f && age <= effect->particle_lifetime)) {
                        continue;
                    }
                    debris_collide_pt.x = sphere->momentum.x * age;
                    debris_collide_pt.y = sphere->momentum.y * age;
                    debris_collide_pt.z = sphere->momentum.z * age;
                    debris_collide_pt.y = age * age * effect->gravity + debris_collide_pt.y;
                    debris_collide_pt.x += sphere->position.x;
                    debris_collide_pt.y += sphere->position.y;
                    debris_collide_pt.z += sphere->position.z;
                    time = age / effect->particle_lifetime;
                    {
                        i32 segment;
                        f32 numerator;
                        f32 denominator;
                        effect_radius = 0.0f;
                        for (segment = 0; segment < 7; ++segment) {
                            if (time >= collision->collision_keys[segment].time && time <= collision->collision_keys[segment + 1].time) {
                                numerator = time - collision->collision_keys[segment].time;
                                denominator = collision->collision_keys[segment + 1].time - collision->collision_keys[segment].time;
                                effect_radius = collision->collision_keys[segment].value +
                                                (numerator / denominator) * (collision->collision_keys[segment + 1].value -
                                                                             collision->collision_keys[segment].value);
                                break;
                            }
                        }
                    }
                    if (effect_radius <= 0.0f) {
                        continue;
                    }
                    dx = position->x - debris_collide_pt.x;
                    dy = position->y - debris_collide_pt.y;
                    dz = position->z - debris_collide_pt.z;
                    if (y_scale != 1.0f) {
                        dy *= (radius + effect_radius) / (radius * y_scale + effect_radius);
                    }
                    if (dx * dx + dy * dy + dz * dz < (radius + effect_radius) * (radius + effect_radius)) {
                        return 1;
                    }
                }
            }
        }
        return 0;
    }

    i32 numspherecolldata = 0;
    DEBRIS_COLLISION_ENTRY *spherecolldata = 0;

    i32 DebrisCollisionCheckScaleYFlag(NUVEC *position, f32 radius, f32 y_scale, u8 flags) {
        i32 i;
        for (i = 0; i < numspherecolldata; ++i) {
            if ((spherecolldata[i].flags & flags) != 0 &&
                DebrisSingleCollisionCheckScaleYFlag(spherecolldata[i].key_index, position, radius, y_scale, flags) != 0) {
                return spherecolldata[i].key_index;
            }
        }
        return -1;
    }

