    i32 edanim_nearest_param_id = 0;
    NUGSCN *edbits_base_scene = 0;
    NUVEC edanim_cam_pos = {0};
    i32 edanim_nearest = 0;

    void edanimDetermineNearestAnim(f32 distance) {
        nuhspecial_s special;
        NUVEC delta;
        f32 candidate;
        i32 i;
        if (edbits_base_scene == NULL) {
            return;
        }
        if (edanim_nearest != -1) {
            NuGScnGetSpecial(&special, edbits_base_scene, edanim_nearest);
            NuVecSub(&delta, &edanim_cam_pos, NuSpecialGetPos(&special));
            candidate = delta.x * delta.x + delta.y * delta.y + delta.z * delta.z;
            if (candidate == 0.0f) {
                return;
            }
        }
        edanim_nearest = -1;
        edanim_nearest_param_id = -1;
        for (i = 0; i < NuGScnNumSpecials(edbits_base_scene); ++i) {
            NuGScnGetSpecial(&special, edbits_base_scene, i);
            NuVecSub(&delta, &edanim_cam_pos, NuSpecialGetPos(&special));
            candidate = delta.x * delta.x + delta.y * delta.y + delta.z * delta.z;
            if (distance < 0.0f || candidate < distance) {
                distance = candidate;
                edanim_nearest = i;
            }
        }
        if (edanim_nearest != -1) {
            for (i = 0; i < 64; ++i) {
                if (AnimParams[i].instance_id == edanim_nearest) {
                    edanim_nearest_param_id = i;
                    return;
                }
            }
        }
    }

    i32 edanim_nearest_particle = 0;

    void edanimDetermineNearestParticle(float distance) {
        nuhspecial_s special;
        struct nuvec_s *base_position;
        NUVEC delta;
        NUVEC world_position;
        f32 length;
        i32 particle;
        if (edanim_nearest == -1 || edanim_nearest_param_id == -1) {
            edanim_nearest_particle = -1;
            return;
        }

        NuGScnGetSpecial(&special, edbits_base_scene, edanim_nearest);
        base_position = NuSpecialGetPos(&special);

        if (edanim_nearest_particle != -1) {
            NuVecAdd(&world_position, base_position,
                     ((NUVEC *)(AnimParams[edanim_nearest_param_id].effect_positions[edanim_nearest_particle])));
            NuVecSub(&delta, &edanim_cam_pos, &world_position);
            length = delta.x * delta.x + delta.y * delta.y + delta.z * delta.z;
            if (length == 0.0f) {
                return;
            }
        }
        edanim_nearest_particle = -1;
        for (particle = 0; particle < AnimParams[edanim_nearest_param_id].effect_count; ++particle) {
            f32 candidate;
            NuVecAdd(&world_position, base_position, ((NUVEC *)(AnimParams[edanim_nearest_param_id].effect_positions[particle])));
            NuVecSub(&delta, &edanim_cam_pos, &world_position);
            candidate = delta.x * delta.x + delta.y * delta.y + delta.z * delta.z;
            if (distance < 0.0f || candidate < distance) {
                distance = candidate;
                edanim_nearest_particle = particle;
            }
        }
    }

    i32 edanim_nearest_sound = 0;

    void edanimDetermineNearestSound(float distance) {
        nuhspecial_s special;
        struct nuvec_s *base_position;
        NUVEC delta;
        NUVEC world_position;
        f32 length;
        i32 sound;
        if (edanim_nearest == -1 || edanim_nearest_param_id == -1) {
            edanim_nearest_sound = -1;
            return;
        }

        NuGScnGetSpecial(&special, edbits_base_scene, edanim_nearest);
        base_position = NuSpecialGetPos(&special);

        if (edanim_nearest_sound != -1) {
            NuVecAdd(&world_position, base_position, &AnimParams[edanim_nearest_param_id].sound_positions[edanim_nearest_sound]);
            NuVecSub(&delta, &edanim_cam_pos, &world_position);
            length = delta.x * delta.x + delta.y * delta.y + delta.z * delta.z;
            if (length == 0.0f) {
                return;
            }
        }
        edanim_nearest_sound = -1;
        for (sound = 0; sound < AnimParams[edanim_nearest_param_id].sound_count; ++sound) {
            f32 candidate;
            NuVecAdd(&world_position, base_position, &AnimParams[edanim_nearest_param_id].sound_positions[sound]);
            NuVecSub(&delta, &edanim_cam_pos, &world_position);
            candidate = delta.x * delta.x + delta.y * delta.y + delta.z * delta.z;
            if (distance < 0.0f || candidate < distance) {
                distance = candidate;
                edanim_nearest_sound = sound;
            }
        }
    }

