    /* Flags are deliberately not compacted by this helper. */
    void edanimSoundDestroy(i32 parameter_index, i32 sound_index) {
        i32 i;
        for (i = sound_index; i < AnimParams[parameter_index].sound_count - 1; ++i) {
            AnimParams[parameter_index].sound_ids[i] = AnimParams[parameter_index].sound_ids[i + 1];
            AnimParams[parameter_index].sound_values[i] = AnimParams[parameter_index].sound_values[i + 1];
            memcpy(&AnimParams[parameter_index].sound_positions[i], &AnimParams[parameter_index].sound_positions[i + 1], sizeof(NUVEC));
            strcpy(AnimParams[parameter_index].sound_names[i], AnimParams[parameter_index].sound_names[i + 1]);
        }
        --AnimParams[parameter_index].sound_count;
    }

    i32 edanim_emitrotz = 0;
    i32 edanim_emitroty = 0;

    void edanimParticlePlace(i32 particle_index, NUVEC *position) {
        nuhspecial_s special;
        NuGScnGetSpecial(&special, edbits_base_scene, edanim_nearest);
        NuVecSub((NUVEC *)AnimParams[edanim_nearest_param_id].effect_positions[particle_index], position, NuSpecialGetPos(&special));
        AnimParams[edanim_nearest_param_id].effect_angles[particle_index] = edanim_emitrotz;
        AnimParams[edanim_nearest_param_id].effect_angle_ranges[particle_index] = edanim_emitroty;
    }

    i32 edanim_particle_type = 0;

    void edanimParticleCreate(NUVEC *position) {
        i32 index = AnimParams[edanim_nearest_param_id].effect_count;
        if (index != 8 && edanim_particle_type != -1) {
            edanimParticlePlace(index, position);
            AnimParams[edanim_nearest_param_id].effect_ids[index] = edanim_particle_type;
            strcpy(AnimParams[edanim_nearest_param_id].effect_names[index], debtab[edanim_particle_type]->name);
            AnimParams[edanim_nearest_param_id].effect_intervals[index] = 60;
            AnimParams[edanim_nearest_param_id].effect_flags[index] = 0;
            ++AnimParams[edanim_nearest_param_id].effect_count;
        }
    }

    void edanimParticleDestroy(i32 parameter_index, i32 particle_index) {
        i32 index;
        for (index = particle_index; index < AnimParams[parameter_index].effect_count - 1; ++index) {
            AnimParams[parameter_index].effect_ids[index] = AnimParams[parameter_index].effect_ids[index + 1];
            AnimParams[parameter_index].effect_intervals[index] = AnimParams[parameter_index].effect_intervals[index + 1];
            AnimParams[parameter_index].effect_flags[index] = AnimParams[parameter_index].effect_flags[index + 1];
            memcpy(AnimParams[parameter_index].effect_positions[index], AnimParams[parameter_index].effect_positions[index + 1],
                   sizeof(NUVEC));
            strcpy(AnimParams[parameter_index].effect_names[index], AnimParams[parameter_index].effect_names[index + 1]);
        }
        --AnimParams[parameter_index].effect_count;
    }

    i32 edanimFileSave(char *path) {
        nuhspecial_s special;
        char name[20];
        i32 count;
        i32 i;
        i32 index;
        count = 0;
        for (i = 0; i < 64; ++i) {
            if (AnimParams[i].instance_id != -1) {
                ++count;
            }
        }
        EdFileSetMedia(1);
        if (EdFileOpen(path, 1)) {
            EdFileSetReadWrongEndianess(1);
            EdFileWriteInt(6);
            EdFileWriteInt(count);
            for (i = 0; i < 64; ++i) {
                if (AnimParams[i].instance_id == -1) {
                    continue;
                }
                NuGScnGetSpecial(&special, edbits_base_scene, AnimParams[i].instance_id);
                strncpy(name, NuSpecialGetName(&special), sizeof(name));
                name[sizeof(name) - 1] = 0;
                EdFileWrite(name, sizeof(name));
                EdFileWriteInt(AnimParams[i].effect_count);
                EdFileWriteInt(AnimParams[i].sound_count);
                EdFileWriteInt(AnimParams[i].control_mode);
                EdFileWriteInt(AnimParams[i].control_switch);
                EdFileWriteFloat(AnimParams[i].control_distance);
                EdFileWriteFloat(AnimParams[i].switch_delay);
                for (index = 0; index < AnimParams[i].effect_count; ++index) {
                    EdFileWrite(AnimParams[i].effect_names[index], sizeof(AnimParams[i].effect_names[index]));
                    EdFileWriteInt(AnimParams[i].effect_intervals[index]);
                    EdFileWriteInt(AnimParams[i].effect_flags[index]);
                    EdFileWriteNuVec((NUVEC *)AnimParams[i].effect_positions[index]);
                    EdFileWriteShort(AnimParams[i].effect_angles[index]);
                    EdFileWriteShort(AnimParams[i].effect_angle_ranges[index]);
                }
                for (index = 0; index < AnimParams[i].sound_count; ++index) {
                    EdFileWrite(AnimParams[i].sound_names[index], sizeof(AnimParams[i].sound_names[index]));
                    EdFileWriteInt(AnimParams[i].sound_flags[index]);
                    EdFileWriteFloat(AnimParams[i].sound_values[index]);
                    EdFileWriteNuVec(&AnimParams[i].sound_positions[index]);
                }
                EdFileWriteFloat(AnimParams[i].bounce_impulse);
                EdFileWriteFloat(AnimParams[i].bounce_spring);
                EdFileWriteFloat(AnimParams[i].bounce_damping);
            }
            EdFileClose();
            EdFileSetReadWrongEndianess(0);
            return 1;
        }
        return 0;
    }

