    i32 edanimLookupSpecial(char *name, NUGSCN *scene) {
        nuhspecial_s special;
        i32 index;
        if (scene != NULL) {
            for (index = 0; index < NuGScnNumSpecials(scene); ++index) {
                NuGScnGetSpecial(&special, scene, index);
                if (NuStrNICmp(NuSpecialGetName(&special), name, 19) == 0) {
                    return index;
                }
            }
        }
        return -1;
    }

