    void edbitsDoSingleDump(i32 face) {
        char filename[32];
        i32 index;
        index = 0;
        sprintf(filename, "pictures\\cub%03d_%d.bmp", index, face);
        while (NuFileSize(filename) > 0 && index != 999) {
            ++index;
            sprintf(filename, "pictures\\cub%03d_%d.bmp", index, face);
        }
        sprintf(filename, "pictures\\cub%03d_", index);
        NuPs2VideoScreenDump(filename, 1, 1.0f, 1.0f, face, 0, 0);
    }

    i32 edbits_cubecount = 0;

    i32 edbitsStartCubemapDump(void) {
        if (edbits_cubecount != 0) {
            return 0;
        }
        edbits_cubecount = 65;
        NuRndrDoingScreenGrab = 1;
        return 1;
    }

    f32 edbits_cubemap_fov = 1.5708f;
    f32 edbits_cubemap_aspect = 1.0f;
    NUCAMERA *cubemapcam = 0;

    i32 edbitsProcessCubemapDump(void) {
        if (edbits_cubecount != 0) {
            if (cubemapcam == NULL) {
                cubemapcam = NuCameraCreate();
            }
            cubemapcam->fov = edbits_cubemap_fov;
            cubemapcam->aspect = edbits_cubemap_aspect;
            switch (edbits_cubecount) {
                case 60:
                    edmainExtCamera(cubemapcam);
                    edcamSetDist(0.0f);
                    edcamSetAng(0, 0x4000);
                    edcamSet();
                    break;
                case 55:
                    edbitsDoSingleDump(0);
                    break;
                case 50:
                    edcamSetAng(0, 0xc000);
                    edcamSet();
                    break;
                case 45:
                    edbitsDoSingleDump(1);
                    break;
                case 40:
                    edcamSetAng(-0x4000, 0);
                    edcamSet();
                    break;
                case 35:
                    edbitsDoSingleDump(2);
                    break;
                case 30:
                    edcamSetAng(0x4000, 0);
                    edcamSet();
                    break;
                case 25:
                    edbitsDoSingleDump(3);
                    break;
                case 20:
                    edcamSetAng(0, 0);
                    edcamSet();
                    break;
                case 15:
                    edbitsDoSingleDump(4);
                    break;
                case 10:
                    edcamSetAng(0, 0x8000);
                    edcamSet();
                    break;
                case 5:
                    edbitsDoSingleDump(5);
                    break;
                case 1:
                    edmainExtCamera(NULL);
                    NuRndrDoingScreenGrab = 0;
                    break;
            }
            --edbits_cubecount;
        }
        return edbits_cubecount;
    }

    PC_EDBRIDGE edBridges[64] = {0};

    i32 edbriFileSave(char *path) {
        nuhspecial_s special;
        char name[20];
        i32 count = 0;
        i32 i;
        for (i = 0; i < 64; ++i) {
            if (edBridges[i].connection_index != -1) {
                ++count;
            }
        }
        EdFileSetMedia(1);
        if (EdFileOpen(path, 1)) {
            EdFileWriteInt(1);
            EdFileWriteInt(count);
            for (i = 0; i < 64; ++i) {
                if (edBridges[i].connection_index == -1) {
                    continue;
                }
                EdFileWriteNuVec(&edBridges[i].position);
                EdFileWriteFloat(edBridges[i].length);
                EdFileWriteFloat(edBridges[i].width);
                EdFileWriteShort(edBridges[i].rotation_z);
                EdFileWriteShort(edBridges[i].rotation_y);
                EdFileWriteChar(edBridges[i].plank_count);
                EdFileWriteChar(edBridges[i].post_interval);
                if (edBridges[i].special_20 == -1) {
                    name[0] = 0;
                } else {
                    NuGScnGetSpecial(&special, edbits_base_scene, edBridges[i].special_20);
                    strncpy(name, NuSpecialGetName(&special), sizeof(name));
                }
                name[19] = 0;
                EdFileWrite(name, 20);
                if (edBridges[i].special_24 == -1) {
                    name[0] = 0;
                } else {
                    NuGScnGetSpecial(&special, edbits_base_scene, edBridges[i].special_24);
                    strncpy(name, NuSpecialGetName(&special), sizeof(name));
                }
                name[19] = 0;
                EdFileWrite(name, 20);
                EdFileWriteFloat(edBridges[i].tension);
                EdFileWriteFloat(edBridges[i].damping);
                EdFileWriteFloat(edBridges[i].gravity);
                EdFileWriteFloat(edBridges[i].player_weight);
                EdFileWriteFloat(edBridges[i].rope_height);
                EdFileWriteFloat(edBridges[i].stability);
                EdFileWriteChar(edBridges[i].red);
                EdFileWriteChar(edBridges[i].green);
                EdFileWriteChar(edBridges[i].blue);
                EdFileWriteChar(edBridges[i].alpha);
            }
            EdFileClose();
            return 1;
        }
        return 0;
    }

    void edbricbFileSave(eduimenu_s *menu, eduiitem_s *unused1, u32 unused2) {
        char name[256];
        char directory[256];
        char extension[256];
        char path[256];
        if (edbits_level_save_directory[0] == 0) {
            sprintf(directory, ".");
        } else {
            strcpy(directory, edbits_level_save_directory);
        }
        if (edbits_level_save_name[0] == 0) {
            sprintf(name, "bridge");
        } else {
            strcpy(name, edbits_level_save_name);
        }
        if (edbits_level_save_extension[0] == 0) {
            sprintf(extension, "bri");
        } else {
            strcpy(extension, edbits_level_save_extension);
        }
        sprintf(path, "%s\\%s.%s", directory, name, extension);
        if (edbriFileSave(path)) {
            eduiCreateMessageMenu(menu, "Saved OK", 1);
        } else {
            eduiCreateMessageMenu(menu, "File Save Error", 0);
        }
    }

    i32 edbri_page_used[8] = {0};

    void edbriStopPage(i8 page) {
        i32 index;
        if (edbri_page_used[page]) {
            for (index = 0; index < 64; ++index) {
                PC_EDBRIDGE *bridge = &edBridges[index];
                if (bridge->connection_index == page && bridge->instance_id != -1) {
                    NuBridgeRemove(bridge->instance_id);
                    bridge->instance_id = -1;
                }
            }
        }
    }

    i32 edbri_bridges_used = 0;
    NUGSCN *edbri_page_scene[8] = {0};

    void edbriClearPage(i8 page) {
        i32 index;
        edbriStopPage(page);
        for (index = 0; index < 64; ++index) {
            if (edBridges[index].connection_index == page) {
                edBridges[index].connection_index = -1;
                --edbri_bridges_used;
            }
        }
        edbri_page_used[page] = 0;
        edbri_page_scene[page] = NULL;
    }

