    NUVEC edgra_cam_pos = {0};
    i32 edgra_nearest_instance = 0;

    void edgraDetermineNearestInstance(f32 distance) {
        NUVEC delta;
        i32 individual;
        i32 i;
        f32 candidate;
        if (edgra_nearest == -1) {
            edgra_nearest_instance = -1;
            return;
        }
        individual = GrassClumps[edgra_nearest].individual_index;
        if (edgra_nearest_instance != -1) {
            NuVecAdd(&delta, &GrassClumps[edgra_nearest].position,
                     &IndGrassClumps[EDGRA_MAX_UNITS_PER_INDIVIDUAL_CLUMP * individual + edgra_nearest_instance].position);
            NuVecSub(&delta, &edgra_cam_pos, &delta);
            candidate = delta.x * delta.x + delta.y * delta.y + delta.z * delta.z;
            if (candidate == 0.0f) {
                return;
            }
        }
        edgra_nearest_instance = -1;
        for (i = 0; i < GrassClumps[edgra_nearest].element_count; ++i) {
            NuVecAdd(&delta, &GrassClumps[edgra_nearest].position,
                     &IndGrassClumps[EDGRA_MAX_UNITS_PER_INDIVIDUAL_CLUMP * individual + i].position);
            NuVecSub(&delta, &edgra_cam_pos, &delta);
            candidate = delta.x * delta.x + delta.y * delta.y + delta.z * delta.z;
            if (distance < 0.0f || candidate < distance) {
                distance = candidate;
                edgra_nearest_instance = i;
            }
        }
    }

    f32 edgra_global_fadein = 15.0f;
    f32 edgra_global_fadeout = 25.0f;

    i32 edgraFileSave(char *path) {
        nuhspecial_s special;
        char name[20];
        i32 clump_count = 0;
        i32 element_count = 0;
        i32 i;
        i32 j;
        for (i = 0; i < EDGRA_MAX_CLUMPS; ++i) {
            if (GrassClumps[i].element_count) {
                ++clump_count;
                element_count += GrassClumps[i].element_count;
            }
        }
        EdFileSetMedia(1);
        if (EdFileOpen(path, 1)) {
            EdFileSetReadWrongEndianess(1);
            EdFileWriteInt(9);
            EdFileWriteFloat(edgra_global_fadein);
            EdFileWriteFloat(edgra_global_fadeout);
            EdFileWriteInt(clump_count);
            EdFileWriteInt(element_count);
            for (i = 0; i < EDGRA_MAX_CLUMPS; ++i) {
                if (!GrassClumps[i].element_count) {
                    continue;
                }
                NuGScnGetSpecial(&special, edbits_base_scene, GrassClumps[i].special_index);
                strncpy(name, NuSpecialGetName(&special), sizeof(name));
                name[19] = 0;
                EdFileWrite(name, 20);
                EdFileWriteInt(GrassClumps[i].element_count);
                EdFileWriteNuVec(&GrassClumps[i].position);
                EdFileWriteFloat(GrassClumps[i].size);
                EdFileWriteFloat(GrassClumps[i].wind);
                EdFileWriteInt(GrassClumps[i].flags);
                EdFileWriteFloat(GrassClumps[i].bend_height);
                EdFileWriteChar(GrassClumps[i].area_shape);
                EdFileWriteChar(GrassClumps[i].distribution);
                EdFileWriteChar(GrassClumps[i].kind);
                EdFileWriteInt(GrassClumps[i].seed);
                EdFileWriteFloat(GrassClumps[i].min_model_size);
                EdFileWriteFloat(GrassClumps[i].max_model_size);
                EdFileWriteShort(GrassClumps[i].rotation_z);
                EdFileWriteShort(GrassClumps[i].rotation_y);
                EdFileWriteFloat(GrassClumps[i].near_distance);
                EdFileWriteFloat(GrassClumps[i].far_distance);
                EdFileWriteChar(GrassClumps[i].follow_terrain);
                EdFileWriteChar(GrassClumps[i].follow_slope);
                EdFileWriteFloat(GrassClumps[i].terrain_offset);
                if (GrassClumps[i].kind == 3) {
                    for (j = 0; j < GrassClumps[i].element_count; ++j) {
                        EdFileWriteNuVec(
                            &IndGrassClumps[EDGRA_MAX_UNITS_PER_INDIVIDUAL_CLUMP * GrassClumps[i].individual_index + j].position);
                        EdFileWriteFloat(IndGrassClumps[EDGRA_MAX_UNITS_PER_INDIVIDUAL_CLUMP * GrassClumps[i].individual_index + j].scale);
                        EdFileWriteShort(
                            IndGrassClumps[EDGRA_MAX_UNITS_PER_INDIVIDUAL_CLUMP * GrassClumps[i].individual_index + j].rotation_z);
                        EdFileWriteShort(
                            IndGrassClumps[EDGRA_MAX_UNITS_PER_INDIVIDUAL_CLUMP * GrassClumps[i].individual_index + j].rotation_y);
                    }
                }
                for (j = 0; j < GrassClumps[i].element_count; ++j) {
                    EdFileWriteNuVec(&GrassClumps[i].vector_buffer[j]);
                }
            }
            EdFileSetReadWrongEndianess(0);
            EdFileClose();
            return 1;
        }
        return 0;
    }

