    void *edgra_free_vecbuffer = 0;
    NUMTX *edgra_mtxbuffer = 0;
    NUVEC *edgra_vecbuffer = 0;

    void edgraInit(void) {
        VARIPTR *buffer;
        i32 index;
        edgraClumpsReset();
        edgra_mtl = NuMtlCreate3D(1);
        (edgra_mtl)->diffuse_r = 0.5f;
        (edgra_mtl)->diffuse_g = 0.5f;
        (edgra_mtl)->diffuse_b = 0.5f;
        (edgra_mtl)->attribs.cull_mode = NUMTL_CULL_NONE;
        (edgra_mtl)->attribs.z_mode = NUMTL_ZMODE_NORMAL;
        (edgra_mtl)->opacity = 1.0f;
        (edgra_mtl)->attribs.alpha_mode = NUMTL_ALPHA_OPAQUE;
        NuMtlUpdate(edgra_mtl);
        edgra_mtl_zoff = NuMtlCreate(1);
        (edgra_mtl_zoff)->diffuse_r = 0.5f;
        (edgra_mtl_zoff)->diffuse_g = 0.5f;
        (edgra_mtl_zoff)->diffuse_b = 0.5f;
        (edgra_mtl_zoff)->attribs.cull_mode = NUMTL_CULL_NONE;
        (edgra_mtl_zoff)->attribs.z_mode = NUMTL_ZMODE_OFF;
        (edgra_mtl_zoff)->opacity = 1.0f;
        (edgra_mtl_zoff)->attribs.alpha_mode = NUMTL_ALPHA_OPAQUE;
        NuMtlUpdate(edgra_mtl_zoff);
        buffer = gra_ptr;
        if (buffer == NULL) {
            edgra_mtxbuffer = (NUMTX *)NuAlloc(0xc0080, "d:\\projects\\game_saga\\gameapi.saga\\gamelib\\edgra.c", 0xb0a);
            edgra_vecbuffer = (NUVEC *)NuAlloc(0x24000, "d:\\projects\\game_saga\\gameapi.saga\\gamelib\\edgra.c", 0xb0c);
        } else {
            edgra_mtxbuffer = (NUMTX *)((buffer->addr + 15) & ~15u);
            buffer->addr = ((buffer->addr + 15) & ~15u) + 0xc0080;
            edgra_vecbuffer = (NUVEC *)((buffer->addr + 15) & ~15u);
            buffer->addr = ((buffer->addr + 15) & ~15u) + 0x24000;
        }
        for (index = 0; index < EDGRA_MAX_CLUMPS; ++index) {
            GrassClumps[index].vector_buffer = NULL;
        }
        edgra_free_vecbuffer = edgra_vecbuffer;
        edgra_instance_type = -1;
    }

