    struct eduiitem_s *grad_size_w_item = 0;
    struct eduiitem_s *grad_size_h_item = 0;

    static void cbPtlCopySize(eduimenu_s *unused0, eduiitem_s *item, u32 unused2) {
        DEBRIS_INFO *effect;
        edui_gradient_pick_s *gradient;
        i32 instance;
        i32 i;
        f32 grey;
        if (edpp_nearest == -1) {
            return;
        }
        instance = edpp_ptls[edpp_nearest].instance_id;
        if (instance == -1) {
            return;
        }
        effect = debtab[debkeydata[instance].effect_index];
        for (i = 0; i < 8; ++i) {
            if (item->data == 1) {
                effect->height_keys[i].time = effect->width_keys[i].time;
                effect->height_keys[i].value = effect->width_keys[i].value;
            } else {
                effect->width_keys[i].time = effect->height_keys[i].time;
                effect->width_keys[i].value = effect->height_keys[i].value;
            }
        }
        if (item->data == 1) {
            gradient = (edui_gradient_pick_s *)grad_size_h_item;
        } else {
            gradient = (edui_gradient_pick_s *)grad_size_w_item;
        }
        while (gradient->first_stage != NULL) {
            eduiGradStageDelete(gradient, gradient->first_stage);
        }
        for (i = 0; i < 8; ++i) {
            if (item->data == 1) {
                grey = (effect->height_keys[i].value - effect->min_size) / (effect->max_size - effect->min_size);
                eduiGradStageAddRGB((edui_gradient_pick_s *)grad_size_h_item, effect->height_keys[i].time, grey, grey, grey);
                if (effect->height_keys[i].time == 1.0f) {
                    break;
                }
            } else {
                grey = (effect->width_keys[i].value - effect->min_size) / (effect->max_size - effect->min_size);
                eduiGradStageAddRGB((edui_gradient_pick_s *)grad_size_w_item, effect->width_keys[i].time, grey, grey, grey);
                if (effect->width_keys[i].time == 1.0f) {
                    break;
                }
            }
        }
        GenericDebinfoDmaTypeUpdate(effect);
    }
    struct edui_slider_s *grad_size_min_item = 0;
    struct edui_slider_s *grad_size_max_item = 0;

    static void cbPtlApplySize(eduimenu_s *unused0, eduiitem_s *unused1, u32 unused2) {
        EDUI_GRADIENT_STAGE stages[8];
        DEBRIS_INFO *effect;
        i32 count;
        i32 instance;
        i32 i;
        f32 minimum;
        f32 maximum;
        if (!grad_size_min_item || !grad_size_max_item || !grad_size_h_item || !grad_size_w_item) {
            return;
        }
        count = eduiGradPickRead(grad_size_w_item, stages, 8);
        minimum = grad_size_min_item->value;
        maximum = grad_size_max_item->value;
        if (count >= 2 && count <= 8 && edpp_nearest != -1) {
            instance = edpp_ptls[edpp_nearest].instance_id;
            if (instance != -1) {
                effect = debtab[debkeydata[instance].effect_index];
                for (i = 0; i < count; ++i) {
                    effect->width_keys[i].time = stages[i].time;
                    effect->width_keys[i].value = stages[i].red * (maximum - minimum) + minimum;
                }
                effect->min_size = minimum;
                effect->max_size = maximum;
                GenericDebinfoDmaTypeUpdate(effect);
            }
        }
        count = eduiGradPickRead(grad_size_h_item, stages, 8);
        if (count >= 2 && count <= 8 && edpp_nearest != -1) {
            instance = edpp_ptls[edpp_nearest].instance_id;
            if (instance != -1) {
                effect = debtab[debkeydata[instance].effect_index];
                for (i = 0; i < count; ++i) {
                    effect->height_keys[i].time = stages[i].time;
                    effect->height_keys[i].value = stages[i].red * (maximum - minimum) + minimum;
                }
                effect->min_size = minimum;
                effect->max_size = maximum;
                GenericDebinfoDmaTypeUpdate(effect);
            }
        }
    }
    struct eduiitem_s *grad_rot_item = 0;
    struct edui_slider_s *grad_rot_min_item = 0;
    struct edui_slider_s *grad_rot_max_item = 0;

    static void cbPtlApplyRot(eduimenu_s *unused0, eduiitem_s *unused1, u32 unused2) {
        EDUI_GRADIENT_STAGE stages[8];
        DEBRIS_INFO *effect;
        i32 count;
        i32 instance;
        i32 i;
        f32 minimum;
        f32 maximum;
        f32 angle;
        if (!(!grad_rot_min_item || !grad_rot_max_item || !grad_rot_item)) {
            count = eduiGradPickRead(grad_rot_item, stages, 8);
            minimum = grad_rot_min_item->value;
            maximum = grad_rot_max_item->value;
            if (minimum == maximum) {
                maximum += 0.1f;
            }
            if (count < 2 || count > 8 || edpp_nearest == -1) {
                return;
            }
            instance = edpp_ptls[edpp_nearest].instance_id;
            if (instance == -1) {
                return;
            }
            effect = debtab[debkeydata[instance].effect_index];
            for (i = 0; i < count; ++i) {
                effect->rotation_keys[i].time = stages[i].time;
                angle = stages[i].red * (maximum - minimum) + minimum;
                effect->rotation_keys[i].value = (f32)(i32)(angle * (65536.0f / 360.0f));
            }
            effect->min_rotation = minimum;
            effect->max_rotation = maximum;
            GenericDebinfoDmaTypeUpdate(effect);
        }
    }
    struct eduimenu_s *ptltypemenu = 0;

    void cbPtlSelType(eduimenu_s *menu, eduiitem_s *item, u32 unused2) {
        ptltypemenu = NULL;
        edpp_active_menu = NULL;
        edpp_create_type = item->data;
        eduiMenuDetach(menu);
        eduiMenuDestroy(menu);
    }

    void cbPtlSelGSort(eduimenu_s *menu, eduiitem_s *item, u32 unused2) {
        DEBRIS_INFO *effect;
        eduiMenuDetach(menu);
        edpp_active_menu = NULL;
        if (edpp_nearest == -1 || edpp_ptls[edpp_nearest].instance_id == -1) {
            return;
        }
        effect = debtab[debkeydata[edpp_ptls[edpp_nearest].instance_id].effect_index];
        if (effect->generator_type == item->data) {
            return;
        }
        if (effect->generator_type == DEBRIS_GENERATOR_RADIAL && item->data == DEBRIS_GENERATOR_IMPROVED_RADIAL) {
            effect->rotor_speed_y *= 0.5f;
            effect->emitter_random_extent.z *= 0.5f;
            effect->emitter_velocity.z *= 0.5f;
        } else if (effect->generator_type == DEBRIS_GENERATOR_IMPROVED_RADIAL && item->data == DEBRIS_GENERATOR_RADIAL) {
            effect->rotor_speed_y *= 2.0f;
            effect->emitter_random_extent.z *= 2.0f;
            effect->emitter_velocity.z *= 2.0f;
        } else if (!((effect->generator_type == DEBRIS_GENERATOR_RADIAL && item->data == DEBRIS_GENERATOR_STAR_RADIAL) ||
                     (effect->generator_type == DEBRIS_GENERATOR_STAR_RADIAL && item->data == DEBRIS_GENERATOR_RADIAL))) {
            /* Clears momentum_random_x through emitter_velocity (0x4c-0x6f). */
            memset(&effect->momentum_random_x, 0, 9 * sizeof(f32));
            effect->scale_in_time = 0.0f;
            effect->trail_count = 0;
        }
        effect->generator_type = (u8)item->data;
        debkeydata[edpp_ptls[edpp_nearest].instance_id].generator = gensorttab[item->data];
    }

    void cbPtlSelGCode(eduimenu_s *menu, eduiitem_s *item, u32 unused2) {
        eduiMenuDetach(menu);
        edpp_active_menu = NULL;
        if (edpp_nearest == -1 || edpp_ptls[edpp_nearest].instance_id == -1) {
            return;
        }
        debtab[debkeydata[edpp_ptls[edpp_nearest].instance_id].effect_index]->momentum_adjustment_type = (i8)(item->data - 1);
        debkeydata[edpp_ptls[edpp_nearest].instance_id].momentum_adjuster = gencodetab[item->data - 1];
    }
