    void edptlcbSetDetail(eduimenu_s *unused0, eduiitem_s *item, u32 unused2) {
        i32 instance_id;
        if (edpp_nearest == 0) {
            return;
        }
        if (item->highlighted) {
            edpp_ptls[edpp_nearest].detail_levels |= (i8)item->data;
        } else {
            edpp_ptls[edpp_nearest].detail_levels &= ~(i8)item->data;
        }
        instance_id = edpp_ptls[edpp_nearest].instance_id;
        if (instance_id == -1) {
            return;
        }
        if (instance_id == EDPP_SHELVED) {
            return;
        }
        edppDebrisSetDetailLevels(instance_id, edpp_ptls[edpp_nearest].detail_levels);
    }
