    static void cbPtlDefaultCollEnv(eduimenu_s *menu, eduiitem_s *unused1, u32 unused2) {
        struct eduimenu_s *parent = NULL;
        DEBRIS_INFO *effect;
        i32 instance;
        i32 i;
        if (edpp_nearest != -1) {
            instance = edpp_ptls[edpp_nearest].instance_id;
            if (instance != -1) {
                effect = debtab[debkeydata[instance].effect_index];
                for (i = 0; i < 8; ++i) {
                    effect->collision_keys[i].time = effect->width_keys[i].time;
                    effect->collision_keys[i].value = effect->width_keys[i].value / 10000.0f;
                }
            }
        }
        if (menu->parent != NULL) {
            parent = menu->parent;
            eduiMenuDetach(menu);
        }
        if (menu->callback != NULL) {
            menu->callback(menu, parent);
        }
    }
    struct eduiitem_s *coll_env_item = 0;

    static void cbPtlApplyCollEnv(eduimenu_s *unused0, eduiitem_s *unused1, u32 unused2) {
        EDUI_GRADIENT_STAGE stages[8];
        DEBRIS_INFO *effect;
        i32 count;
        i32 instance;
        i32 i;
        f32 minimum;
        f32 maximum;
        if (coll_env_item) {
            count = eduiGradPickRead(coll_env_item, stages, 8);
            if (count < 2 || count > 8 || edpp_nearest == -1) {
                return;
            }
            instance = edpp_ptls[edpp_nearest].instance_id;
            if (instance == -1) {
                return;
            }
            effect = debtab[debkeydata[instance].effect_index];
            minimum = effect->min_size / 10000.0f;
            maximum = effect->max_size / 10000.0f;
            for (i = 0; i < count; ++i) {
                effect->collision_keys[i].time = stages[i].time;
                effect->collision_keys[i].value = stages[i].red * (maximum - minimum) + minimum;
            }
        }
    }
    struct eduimenu_s *edptl_soundid_menu = 0;

    void edptlcbSetSoundID(eduimenu_s *menu, eduiitem_s *item, u32 unused2) {
        u32 data;
        u32 sound_index;
        i32 sound_id;
        i32 instance;
        i32 index;
        i32 slot;
        edptl_soundid_menu = NULL;
        data = item->data;
        sound_index = data >> 16;
        sound_id = data - (sound_index << 16);
        if (sound_id == 9999) {
            sound_id = -1;
        }
        if (edpp_nearest != -1) {
            instance = edpp_ptls[edpp_nearest].instance_id;
            if (instance != -1) {
                debtab[debkeydata[instance].effect_index]->sound_data[sound_index * 3] = sound_id;
            }
        }
        for (index = 0; index < 512; ++index) {
            if (edpp_ptls[index].instance_id == -1 || edpp_ptls[index].instance_id == EDPP_SHELVED) {
                continue;
            }
            debkeydata[edpp_ptls[index].instance_id].process_collision_sound = 0;
            for (slot = 0; slot < 4; ++slot) {
                if (debtab[debkeydata[edpp_ptls[index].instance_id].effect_index]->sound_data[slot * 3] != -1) {
                    debkeydata[edpp_ptls[index].instance_id].process_collision_sound = 1;
                }
            }
        }
        eduiMenuDetach(menu);
        eduiMenuDestroy(menu);
    }
    struct eduimenu_s *edptl_soundcontrol_menu = 0;

    void edptlcbSetSoundControl(eduimenu_s *menu, eduiitem_s *item, u32 unused2) {
        u32 data;
        u32 sound_index;
        i32 index;
        i32 slot;
        edptl_soundcontrol_menu = NULL;
        data = item->data;
        sound_index = data >> 16;
        if (edpp_nearest != -1 && edpp_ptls[edpp_nearest].instance_id != -1) {
            debtab[debkeydata[edpp_ptls[edpp_nearest].instance_id].effect_index]->sound_data[sound_index * 3 + 1] =
                data - (sound_index << 16);
        }
        for (index = 0; index < 512; ++index) {
            if (edpp_ptls[index].instance_id == -1 || edpp_ptls[index].instance_id == EDPP_SHELVED) {
                continue;
            }
            for (slot = 0; slot < 4; ++slot) {
                debkeydata[edpp_ptls[index].instance_id].collision_timers[slot] = 9999;
                if (debtab[debkeydata[edpp_ptls[index].instance_id].effect_index]->sound_data[slot * 3 + 1] == 4 ||
                    debtab[debkeydata[edpp_ptls[index].instance_id].effect_index]->sound_data[slot * 3 + 1] == 3) {
                    debkeydata[edpp_ptls[index].instance_id].collision_timers[slot] = 1;
                }
            }
        }
        eduiMenuDetach(menu);
        eduiMenuDestroy(menu);
    }

