    i32 edbits_particle_level_page = 2;
    i32 EdppUseMemcard = 0;

    i32 edppSaveEffects(char *filename, u8 page) {
        i32 effect_count = 0;
        i32 instance_count = 0;
        u8 list = page;
        i32 index;
        i32 key;
        i32 sound_count;
        if (page == 6) {
            page = 1;
        }
        for (index = 1; index < debinf_count; ++index) {
            if (debtab[index] == NULL) {
                continue;
            }
            if (page == 2) {
                ++effect_count;
            } else if (page == 1) {
                if (effecttypes[index].category == page && edbits_particle_level_page == effecttypes[index].page) {
                    ++effect_count;
                }
            } else if (effecttypes[index].category == page) {
                ++effect_count;
            }
        }
        if (EdppUseMemcard != 0) {
            EdFileSetMedia(2);
        } else {
            EdFileSetMedia(1);
        }
        if (EdFileOpen(filename, NUFILE_WRITE) != 0) {
            EdFileSetReadWrongEndianess(1);
            EdFileWriteInt(0x29);
            EdFileWriteInt(effect_count);
            for (index = 1; index < debinf_count; ++index) {
                if (debtab[index] == NULL) {
                    continue;
                }
                if (page != 2) {
                    if (page == 1) {
                        if (effecttypes[index].category != page) {
                            continue;
                        }
                        if (edbits_particle_level_page != effecttypes[index].page) {
                            continue;
                        }
                    } else if (effecttypes[index].category != page) {
                        continue;
                    }
                }
                EdFileWrite(effecttypes[index].name, 16);
                EdFileWriteShort(effecttypes[index].frequency);
                EdFileWriteShort(effecttypes[index].max_particles);
                EdFileWriteFloat(effecttypes[index].emission_start_offset);
                EdFileWriteFloat(effecttypes[index].emission_period);
                EdFileWriteFloat(effecttypes[index].emission_period_random);
                EdFileWriteFloat(effecttypes[index].emission_pause);
                EdFileWriteFloat(effecttypes[index].emission_pause_random);
                EdFileWriteChar(effecttypes[index].generator_type);
                EdFileWriteChar(effecttypes[index].momentum_adjustment_type);
                EdFileWriteChar(effecttypes[index].cutscene_only);
                EdFileWriteChar(effecttypes[index].particle_type);
                EdFileWriteChar(effecttypes[index].camera_facing);
                EdFileWriteFloat(effecttypes[index].fade_delay);
                EdFileWriteFloat(effecttypes[index].cut_on);
                EdFileWriteFloat(effecttypes[index].clip_extent);
                EdFileWriteFloat(effecttypes[index].sound_range);
                EdFileWriteFloat(effecttypes[index].sound_range_override);
                EdFileWriteFloat(effecttypes[index].camera_cutoff_radius);
                EdFileWriteFloat(effecttypes[index].momentum_base);
                EdFileWriteNuVec((NUVEC *)&effecttypes[index].momentum_random_x);
                EdFileWriteNuVec(&effecttypes[index].emitter_random_extent);
                EdFileWriteNuVec(&effecttypes[index].emitter_velocity);
                EdFileWriteFloat(effecttypes[index].file_parameters[0]);
                EdFileWriteFloat(effecttypes[index].file_parameters[1]);
                EdFileWriteFloat(effecttypes[index].file_parameters[2]);
                EdFileWriteFloat(effecttypes[index].file_parameters[3]);
                EdFileWriteFloat(effecttypes[index].file_parameters[4]);
                EdFileWriteFloat(effecttypes[index].file_parameters[5]);
                EdFileWriteFloat(effecttypes[index].file_parameters[6]);
                EdFileWriteFloat(effecttypes[index].file_parameters[7]);
                EdFileWriteFloat(effecttypes[index].file_parameters[8]);
                EdFileWriteFloat(effecttypes[index].file_parameters[9]);
                EdFileWriteFloat(effecttypes[index].file_parameters[10]);
                EdFileWriteFloat(effecttypes[index].file_parameters[11]);
                EdFileWriteFloat(effecttypes[index].gravity);
                EdFileWriteFloat(effecttypes[index].particle_lifetime);
                EdFileWriteShort(effecttypes[index].texture_frames);
                EdFileWriteChar(effecttypes[index].texture_rows);
                EdFileWriteChar(effecttypes[index].frame_divisor);
                EdFileWriteFloat(effecttypes[index].animation_rate.rate);
                EdFileWriteFloat(effecttypes[index].jib_x_frequency);
                EdFileWriteFloat(effecttypes[index].jib_x_amplitude);
                EdFileWriteFloat(effecttypes[index].jib_y_frequency);
                EdFileWriteFloat(effecttypes[index].jib_y_amplitude);
                for (key = 0; key < 8; ++key) {
                    EdFileWriteFloat(effecttypes[index].colour_keys[key].time);
                    EdFileWriteUnsignedChar(effecttypes[index].colour_keys[key].red);
                    EdFileWriteUnsignedChar(effecttypes[index].colour_keys[key].green);
                    EdFileWriteUnsignedChar(effecttypes[index].colour_keys[key].blue);
                    EdFileWriteUnsignedChar(effecttypes[index].colour_keys[key].alpha_unused);
                }
                for (key = 0; key < 8; ++key) {
                    EdFileWriteFloat(effecttypes[index].alpha_keys[key].time);
                    EdFileWriteFloat(effecttypes[index].alpha_keys[key].value);
                }
                EdFileWriteFloat(effecttypes[index].particle_parameter_a);
                EdFileWriteFloat(effecttypes[index].particle_parameter_b);
                EdFileWriteFloat(effecttypes[index].min_size);
                EdFileWriteFloat(effecttypes[index].max_size);
                for (key = 0; key < 8; ++key) {
                    EdFileWriteFloat(effecttypes[index].width_keys[key].time);
                    EdFileWriteFloat(effecttypes[index].width_keys[key].value);
                }
                for (key = 0; key < 8; ++key) {
                    EdFileWriteFloat(effecttypes[index].height_keys[key].time);
                    EdFileWriteFloat(effecttypes[index].height_keys[key].value);
                }
                EdFileWriteFloat(effecttypes[index].min_rotation);
                EdFileWriteFloat(effecttypes[index].max_rotation);
                for (key = 0; key < 8; ++key) {
                    EdFileWriteFloat(effecttypes[index].rotation_keys[key].time);
                    EdFileWriteFloat(effecttypes[index].rotation_keys[key].value);
                }
                for (key = 0; key < 8; ++key) {
                    EdFileWriteFloat(effecttypes[index].scale_keys[key].time);
                    EdFileWriteFloat(effecttypes[index].scale_keys[key].value);
                }
                for (key = 0; key < 8; ++key) {
                    EdFileWriteFloat(effecttypes[index].extra_keys[key].time);
                    EdFileWriteFloat(effecttypes[index].extra_keys[key].value);
                }
                EdFileWriteFloat(effecttypes[index].texture_u0);
                EdFileWriteFloat(effecttypes[index].texture_v0);
                EdFileWriteFloat(effecttypes[index].texture_u1);
                EdFileWriteFloat(effecttypes[index].texture_v1);
                for (key = 0; key < 8; ++key) {
                    EdFileWriteFloat(effecttypes[index].collision_keys[key].time);
                    EdFileWriteFloat(effecttypes[index].collision_keys[key].value);
                }
                EdFileWriteChar(effecttypes[index].process_spheres);
                EdFileWriteChar(effecttypes[index].time_group);
                EdFileWriteChar(effecttypes[index].collision_flags);
                EdFileWriteChar(effecttypes[index].use_explicit_clip_box);
                EdFileWriteNuVec(&effecttypes[index].particle_box);
                EdFileWriteFloat(effecttypes[index].thinning);
                EdFileWriteFloat(effecttypes[index].torus_radius1);
                EdFileWriteFloat(effecttypes[index].torus_radius2);
                EdFileWriteFloat(effecttypes[index].torus_lifetime);
                for (key = 0; key < 8; ++key) {
                    EdFileWriteFloat(effecttypes[index].torus_keys1[key].time);
                    EdFileWriteFloat(effecttypes[index].torus_keys1[key].value);
                }
                for (key = 0; key < 8; ++key) {
                    EdFileWriteFloat(effecttypes[index].torus_keys2[key].time);
                    EdFileWriteFloat(effecttypes[index].torus_keys2[key].value);
                }
                for (key = 0; key < 8; ++key) {
                    EdFileWriteFloat(effecttypes[index].torus_keys3[key].time);
                    EdFileWriteFloat(effecttypes[index].torus_keys3[key].value);
                }
                sound_count = 0;
                if (effecttypes[index].sound_data[0] != -1) {
                    ++sound_count;
                }
                if (effecttypes[index].sound_data[3] != -1) {
                    ++sound_count;
                }
                if (effecttypes[index].sound_data[6] != -1) {
                    ++sound_count;
                }
                if (effecttypes[index].sound_data[9] != -1) {
                    ++sound_count;
                }
                EdFileWriteInt(sound_count);
                for (key = 0; key < 4; ++key) {
                    if (effecttypes[index].sound_data[key * 3] != -1) {
                        EdFileWrite(SfxInfo[effecttypes[index].sound_data[key * 3]].name, 16);
                        EdFileWriteInt(effecttypes[index].sound_data[key * 3 + 1]);
                        EdFileWriteInt(effecttypes[index].sound_data[key * 3 + 2]);
                    }
                }
                EdFileWriteChar(effecttypes[index].trail_count);
                EdFileWriteFloat(effecttypes[index].trail_time);
                EdFileWriteChar(effecttypes[index].radial_segments);
                EdFileWriteFloat(effecttypes[index].radial_floor);
                EdFileWriteFloat(effecttypes[index].scale_in_time);
            }
            if (list == 1 || list == 2) {
                for (index = 0; index < 512; ++index) {
                    if (edpp_ptls[index].instance_id != -1) {
                        ++instance_count;
                    }
                }
                EdFileWriteInt(instance_count);
                for (index = 0; index < 512; ++index) {
                    if (edpp_ptls[index].instance_id == -1) {
                        continue;
                    }
                    EdFileWriteNuVec(&edpp_ptls[index].position);
                    EdFileWriteShort(edpp_ptls[index].rotation_z);
                    EdFileWriteShort(edpp_ptls[index].rotation_y);
                    EdFileWriteShort(edpp_ptls[index].emitter_rotation_z);
                    EdFileWriteShort(edpp_ptls[index].emitter_rotation_y);
                    EdFileWriteShort(edpp_ptls[index].emitter_rotation_x);
                    EdFileWriteFloat(edpp_ptls[index].start_offset);
                    if (edpp_ptls[index].effect_index != -1) {
                        EdFileWrite(debtab[edpp_ptls[index].effect_index]->name, 16);
                    } else {
                        EdFileWrite(edpp_ptls[index].name, 16);
                    }
                    EdFileWriteInt(edpp_ptls[index].switch_type);
                    EdFileWriteInt(edpp_ptls[index].switch_id);
                    EdFileWriteFloat(edpp_ptls[index].switch_variable);
                    EdFileWriteShort(edpp_ptls[index].reflection_rotation_z);
                    EdFileWriteShort(edpp_ptls[index].reflection_rotation_y);
                    EdFileWriteFloat(edpp_ptls[index].reflection_offset);
                    EdFileWriteFloat(edpp_ptls[index].reflection_bounce);
                    EdFileWriteShort(edpp_ptls[index].render_group);
                    EdFileWriteUnsignedShort(edpp_ptls[index].render_priority);
                    EdFileWriteChar(edpp_ptls[index].dynamic_priority);
                    EdFileWriteChar(edpp_ptls[index].detail_levels);
                    EdFileWriteChar(edpp_ptls[index].facing_mode);
                    EdFileWriteShort(edpp_ptls[index].facing_rotation_x);
                    EdFileWriteShort(edpp_ptls[index].facing_rotation_y);
                }
            }
            EdFileSetReadWrongEndianess(0);
            EdFileClose();
            return 1;
        }
        return 0;
    }

    i32 edbits_override_backups = 0;

    void cbFileSaveEffects(eduimenu_s *parent, eduiitem_s *unused1, u32 unused2) {
        i32 valid_page = 1;
        i32 backup_succeeded = 1;
        char original_directory[64] = "";
        char filename[256];
        char backup[256];
        char general_directory[256];
        char general_name[256];
        char general_extension[256];
        char level_directory[256];
        char level_name[256];
        char level_extension[256];
        if (edbits_datapath[0] != '\0') {
            NuFileGetCurrentDirectory(original_directory);
            NuFileSetCurrentDirectory(edbits_datapath);
        }
        if (edbits_general_save_directory[0] == '\0') {
            sprintf(general_directory, ".");
        } else {
            strcpy(general_directory, edbits_general_save_directory);
        }
        if (edbits_general_save_name[0] == '\0') {
            sprintf(general_name, "particle");
        } else {
            strcpy(general_name, edbits_general_save_name);
        }
        if (edbits_general_save_extension[0] == '\0') {
            sprintf(general_extension, "ptl");
        } else {
            strcpy(general_extension, edbits_general_save_extension);
        }
        if (edbits_level_save_directory[0] == '\0') {
            sprintf(level_directory, ".");
        } else {
            strcpy(level_directory, edbits_level_save_directory);
        }
        if (edbits_level_save_name[0] == '\0') {
            sprintf(level_name, "particle");
        } else {
            strcpy(level_name, edbits_level_save_name);
        }
        if (edbits_level_save_extension[0] == '\0') {
            sprintf(level_extension, "ptl");
        } else {
            strcpy(level_extension, edbits_level_save_extension);
        }
        if (edpp_effect_list == 0) {
            if (edpp_save_names[0] != NULL) {
                NuStrCpy(filename, edpp_save_names[0]);
                NuStrCpy(backup, filename);
                NuStrCat(backup, ".bak");
            } else {
                sprintf(filename, "%s\\%s.%s", general_directory, general_name, general_extension);
                sprintf(backup, "%s\\%s.%s.bak", general_directory, general_name, general_extension);
            }
        } else if (edpp_effect_list == 1) {
            if (edpp_save_names[1] != NULL) {
                NuStrCpy(filename, edpp_save_names[1]);
                NuStrCpy(backup, filename);
                NuStrCat(backup, ".bak");
            } else {
                sprintf(filename, "%s\\%s.%s", level_directory, level_name, level_extension);
                sprintf(backup, "%s\\%s.%s.bak", level_directory, level_name, level_extension);
            }
        } else if (edpp_effect_list == 5) {
            if (edpp_save_names[5] != NULL) {
                NuStrCpy(filename, edpp_save_names[5]);
                NuStrCpy(backup, filename);
                NuStrCat(backup, ".bak");
            } else {
                sprintf(filename, "%s\\char.%s", general_directory, general_extension);
                sprintf(backup, "%s\\char.%s.bak", general_directory, general_extension);
            }
        } else {
            valid_page = 0;
        }
        if (EdppUseMemcard == 0 && edbits_override_backups == 0 && valid_page != 0) {
            backup_succeeded = EdFileBackup(filename, backup);
        }
        if (valid_page != 0 && edppSaveEffects(filename, edpp_effect_list) != 0) {
            if (backup_succeeded != 0) {
                edppShowMessage(parent, "Saved OK", 1);
            } else {
                edppShowMessage(parent, "Saved OK - Backup Failed", 1);
            }
        } else {
            edppShowMessage(parent, "File Save Error", 0);
        }
        if (original_directory[0] != '\0') {
            NuFileSetCurrentDirectory(original_directory);
        }
    }

    void FileLoadSingleEffectType(DEBRIS_INFO *destination, i32 version, i8 category) {
        DEBRIS_INFO *effect = destination;
        i32 i;
        char sound_name[16];
        EdFileRead(effect->name, sizeof(effect->name));
        effect->category = (u8)(category);
        if (version < 28) {
            i16 rate = EdFileReadShort();
            if (rate > 0) {
                effect->frequency = (i16)(rate * 60);
            } else if (rate < 0) {
                effect->frequency = (i16)(-60 / rate);
            } else {
                effect->frequency = 0;
            }
        } else {
            effect->frequency = EdFileReadShort();
        }
        effect->max_particles = EdFileReadShort();
        if (version < 28) {
            effect->emission_start_offset = (f32)(EdFileReadShort()) / 60.0f;
            effect->emission_period = (f32)(EdFileReadShort()) / 60.0f;
            effect->emission_period_random = (f32)(EdFileReadShort()) / 60.0f;
            effect->emission_pause = (f32)(EdFileReadShort()) / 60.0f;
            effect->emission_pause_random = (f32)(EdFileReadShort()) / 60.0f;
        } else {
            effect->emission_start_offset = EdFileReadFloat();
            effect->emission_period = EdFileReadFloat();
            effect->emission_period_random = EdFileReadFloat();
            effect->emission_pause = EdFileReadFloat();
            effect->emission_pause_random = EdFileReadFloat();
        }
        if ((f32)effect->frequency != 0.0f && effect->emission_period < 1.0f / (f32)effect->frequency) {
            effect->emission_period = 1.0f / (f32)effect->frequency;
        }

        effect->generator_type = (u8)(EdFileReadChar());
        effect->momentum_adjustment_type = (u8)(EdFileReadChar());
        if (version < 35) {
            effect->cutscene_only = 0;
        } else {
            effect->cutscene_only = (u8)(EdFileReadChar());
        }
        effect->disabled = 0;
        effect->particle_type = (u8)(EdFileReadChar());
        if (version < 39) {
            EdFileReadChar();
        }
        effect->status = 1;
        if (version < 40) {
            effect->camera_facing = 0;
        } else {
            effect->camera_facing = (u8)(EdFileReadChar());
        }

        effect->fade_delay = EdFileReadFloat();
        if (version < 6) {
            effect->cut_on = 0.0f;
            effect->clip_extent = 25.0f;
        } else {
            effect->cut_on = EdFileReadFloat();
            effect->clip_extent = EdFileReadFloat();
        }
        if (version < 10) {
            effect->sound_range = 0.0f;
        } else {
            effect->sound_range = EdFileReadFloat();
        }
        if (version < 23) {
            effect->sound_range_override = 0.0f;
        } else {
            effect->sound_range_override = EdFileReadFloat();
        }
        if (version >= 24) {
            effect->camera_cutoff_radius = EdFileReadFloat();
        } else {
            effect->camera_cutoff_radius = 0.5f;
        }
        if (version < 7) {
            EdFileReadInt();
            EdFileReadInt();
        }
        effect->momentum_base = EdFileReadFloat();
        effect->momentum_random_x = EdFileReadFloat();
        effect->rotor_speed_x = EdFileReadFloat();
        effect->rotor_speed_y = EdFileReadFloat();
        if (version < 18) {
            EdFileReadFloat();
            EdFileReadFloat();
            EdFileReadFloat();
        }
        effect->emitter_random_extent.x = EdFileReadFloat();
        effect->emitter_random_extent.y = EdFileReadFloat();
        effect->emitter_random_extent.z = EdFileReadFloat();
        if (version < 18) {
            EdFileReadFloat();
            EdFileReadFloat();
            EdFileReadFloat();
        }
        if ((version == 18 || version == 19) && effect->generator_type == DEBRIS_GENERATOR_RADIAL) {
            effect->rotor_speed_y = (f32)(effect->rotor_speed_y * 2.0);
            effect->emitter_random_extent.z = (f32)(effect->emitter_random_extent.z * 2.0);
        }
        if (version >= 29) {
            effect->emitter_velocity.x = EdFileReadFloat();
            effect->emitter_velocity.y = EdFileReadFloat();
            effect->emitter_velocity.z = EdFileReadFloat();
        } else {
            effect->emitter_velocity.x = effect->emitter_velocity.y = effect->emitter_velocity.z = 0.0f;
        }

        effect->file_parameters[0] = EdFileReadFloat();
        effect->file_parameters[1] = EdFileReadFloat();
        effect->file_parameters[2] = EdFileReadFloat();
        effect->file_parameters[3] = EdFileReadFloat();
        effect->file_parameters[4] = EdFileReadFloat();
        effect->file_parameters[5] = EdFileReadFloat();
        effect->file_parameters[6] = EdFileReadFloat();
        effect->file_parameters[7] = EdFileReadFloat();
        effect->file_parameters[8] = EdFileReadFloat();
        effect->file_parameters[9] = EdFileReadFloat();
        effect->file_parameters[10] = EdFileReadFloat();
        effect->file_parameters[11] = EdFileReadFloat();
        effect->gravity = EdFileReadFloat();
        effect->particle_lifetime = EdFileReadFloat();
        effect->texture_frames = EdFileReadShort();
        effect->texture_rows = (u8)(EdFileReadChar());
        effect->frame_divisor = (u8)(EdFileReadChar());
        effect->animation_rate.rate = EdFileReadFloat();
        effect->jib_x_frequency = EdFileReadFloat();
        effect->jib_x_amplitude = EdFileReadFloat();
        effect->jib_y_frequency = EdFileReadFloat();
        effect->jib_y_amplitude = EdFileReadFloat();
        if (version >= 33) {
            for (i = 0; i < 8; ++i) {
                effect->colour_keys[i].time = EdFileReadFloat();
                effect->colour_keys[i].red = EdFileReadUnsignedChar();
                effect->colour_keys[i].green = EdFileReadUnsignedChar();
                effect->colour_keys[i].blue = EdFileReadUnsignedChar();
                effect->colour_keys[i].alpha_unused = EdFileReadUnsignedChar();
            }
        } else {
            for (i = 0; i < 8; ++i) {
                effect->colour_keys[i].time = EdFileReadFloat();
                effect->colour_keys[i].red = (u8)((i32)(EdFileReadFloat()));
                effect->colour_keys[i].green = (u8)((i32)(EdFileReadFloat()));
                effect->colour_keys[i].blue = (u8)((i32)(EdFileReadFloat()));
            }
        }
        for (i = 0; i < 8; ++i) {
            effect->alpha_keys[i].time = EdFileReadFloat();
            effect->alpha_keys[i].value = EdFileReadFloat();
        }
        if (version < 21) {
            effect->particle_parameter_a = 0.125f;
            effect->particle_parameter_b = 0.125f;
        } else {
            effect->particle_parameter_a = EdFileReadFloat();
            effect->particle_parameter_b = EdFileReadFloat();
        }
        effect->min_size = EdFileReadFloat();
        effect->max_size = EdFileReadFloat();
        for (i = 0; i < 8; ++i) {
            effect->width_keys[i].time = EdFileReadFloat();
            effect->width_keys[i].value = EdFileReadFloat();
        }
        for (i = 0; i < 8; ++i) {
            effect->height_keys[i].time = EdFileReadFloat();
            effect->height_keys[i].value = EdFileReadFloat();
        }
        effect->min_rotation = EdFileReadFloat();
        effect->max_rotation = EdFileReadFloat();
        for (i = 0; i < 8; ++i) {
            effect->rotation_keys[i].time = EdFileReadFloat();
            effect->rotation_keys[i].value = EdFileReadFloat();
        }
        for (i = 0; i < 8; ++i) {
            effect->scale_keys[i].time = EdFileReadFloat();
            effect->scale_keys[i].value = EdFileReadFloat();
        }
        for (i = 0; i < 8; ++i) {
            effect->extra_keys[i].time = EdFileReadFloat();
            effect->extra_keys[i].value = EdFileReadFloat();
        }
        effect->texture_u0 = EdFileReadFloat();
        effect->texture_v0 = EdFileReadFloat();
        effect->texture_u1 = EdFileReadFloat();
        effect->texture_v1 = EdFileReadFloat();

        if (version >= 3) {
            for (i = 0; i < 8; ++i) {
                effect->collision_keys[i].time = EdFileReadFloat();
                effect->collision_keys[i].value = EdFileReadFloat();
            }
            effect->process_spheres = (u8)(EdFileReadChar());
        } else {
            effect->process_spheres = 0;
        }
        if (version >= 17) {
            effect->time_group = EdFileReadChar();
        } else {
            effect->time_group = DEBRIS_DRAW_AFTER_FOG;
        }
        if (effect->particle_type == DEBRIS_PARTICLE_GLASS) {
            effect->time_group = 2;
        }
        if (version >= 31) {
            effect->collision_flags = (u8)(EdFileReadChar());
        } else {
            effect->collision_flags = 3;
        }
        if (version >= 32) {
            effect->use_explicit_clip_box = (u8)(EdFileReadChar());
            effect->particle_box.x = EdFileReadFloat();
            effect->particle_box.y = EdFileReadFloat();
            effect->particle_box.z = EdFileReadFloat();
        } else {
            effect->use_explicit_clip_box = 0;
            effect->particle_box.x = 1.0f;
            effect->particle_box.y = 1.0f;
            effect->particle_box.z = 1.0f;
        }
        if (version >= 36) {
            f32 thinning = EdFileReadFloat();
            effect->thinning = thinning;
            if (version == 36 && thinning < 4.0f) {
                effect->thinning = 4.0f;
            }
        } else {
            effect->thinning = 4.0f;
        }
        if (version >= 30) {
            effect->torus_radius1 = EdFileReadFloat();
            effect->torus_radius2 = EdFileReadFloat();
            effect->torus_lifetime = EdFileReadFloat();
            for (i = 0; i < 8; ++i) {
                effect->torus_keys1[i].time = EdFileReadFloat();
                effect->torus_keys1[i].value = EdFileReadFloat();
            }
            for (i = 0; i < 8; ++i) {
                effect->torus_keys2[i].time = EdFileReadFloat();
                effect->torus_keys2[i].value = EdFileReadFloat();
            }
            for (i = 0; i < 8; ++i) {
                effect->torus_keys3[i].time = EdFileReadFloat();
                effect->torus_keys3[i].value = EdFileReadFloat();
            }
        } else {
            effect->torus_radius1 = 1.0f;
            effect->torus_radius2 = 0.1f;
            effect->torus_lifetime = 0.0f;
            effect->torus_keys1[0].time = 0.0f;
            effect->torus_keys1[0].value = 0.0f;
            effect->torus_keys2[0].time = 0.0f;
            effect->torus_keys2[0].value = 0.0f;
            effect->torus_keys3[0].time = 0.0f;
            effect->torus_keys3[0].value = 0.0f;
            effect->torus_keys1[1].time = 1.0f;
            effect->torus_keys1[1].value = 1.0f;
            effect->torus_keys2[1].time = 1.0f;
            effect->torus_keys2[1].value = 1.0f;
            effect->torus_keys3[1].time = 1.0f;
            effect->torus_keys3[1].value = 1.0f;
        }

        for (i = 0; i < 8; ++i) {
            effect->particle_keys[i] = -1;
        }
        if (version >= 23) {
            const i32 sound_count = EdFileReadInt();
            for (i = 0; i < sound_count; ++i) {
                EdFileRead(sound_name, sizeof(sound_name));
                effect->sound_data[i * 3] = GetSfxIdN(sound_name, sizeof(sound_name));
                effect->sound_data[i * 3 + 1] = EdFileReadInt();
                effect->sound_data[i * 3 + 2] = EdFileReadInt();
            }
            for (i = sound_count; i < 4; ++i) {
                effect->sound_data[i * 3] = -1;
            }
        } else {
            for (i = 0; i < 4; ++i) {
                if (version >= 11) {
                    effect->sound_data[i * 3] = EdFileReadInt();
                    effect->sound_data[i * 3 + 1] = EdFileReadInt();
                    effect->sound_data[i * 3 + 2] = EdFileReadInt();
                } else {
                    effect->sound_data[i * 3] = -1;
                    effect->sound_data[i * 3 + 1] = 0;
                    effect->sound_data[i * 3 + 2] = 0;
                }
            }
        }
        if (version >= 16) {
            if (version >= 41) {
                effect->trail_count = EdFileReadChar();
            } else {
                effect->trail_count = (i8)EdFileReadInt();
            }
            effect->trail_time = EdFileReadFloat();
        } else {
            effect->trail_count = 0;
            effect->trail_time = 0.0f;
        }
        if (version >= 25) {
            if (version >= 41) {
                effect->radial_segments = (u8)EdFileReadChar();
            } else {
                effect->radial_segments = (u8)EdFileReadInt();
            }
            effect->radial_floor = EdFileReadFloat();
        } else {
            effect->radial_segments = 5;
            effect->radial_floor = 0.5f;
        }
        if (version >= 26) {
            effect->scale_in_time = EdFileReadFloat();
        } else {
            effect->scale_in_time = 0.0f;
        }
        effect->scale = 1.0f;
        effect->base_effect_index = 0;
    }
