    void AddDebrisEffect(i32 *handle, i32 effect_index, f32 x, f32 y, f32 z) {
        i32 i;
        DEBRIS_INFO *effect;
        i32 newly_allocated;
        i32 key_index;
        f32 now;
        newly_allocated = 0;
        if (effect_index == -1 || effect_index == 0 || effect_index >= debinf_count) {
            return;
        }
        effect = debtab[effect_index];
        if (effect == NULL) {
            return;
        }
        if (effect->disabled != 0) {
            return;
        }

        if (*handle == -1) {
            *handle = DebAlloc();
            newly_allocated = 1;
        }
        key_index = *handle;
        if (key_index == -1) {
            return;
        }

        now = effect->time_group == DEBRIS_DRAW_PANEL ? panelglobaltime : globaltime;
        debkeydata[key_index].effect_index = (i16)(effect_index);
        debkeydata[key_index].finite = 0;
        DebrisStartOffset(key_index, effect->emission_start_offset);
        debkeydata[key_index].generator = gensorttab[effect->generator_type];
        debkeydata[key_index].momentum_adjuster = gencodetab[effect->momentum_adjustment_type];
        debkeydata[key_index].finite_count = 0;
        debkeydata[key_index].emitter_rotation_x = 0;
        debkeydata[key_index].emitter_rotation_y = 0;
        debkeydata[key_index].sphere_index = 0;
        debkeydata[key_index].sphere_next_time = 0.0f;
        for (i = 0; i < debtab[effect_index]->process_spheres; ++i) {
            debkeydata[key_index].process_spheres[i].time = -1.0f;
        }
        debkeydata[key_index].emission_position.x = 0.0f;
        debkeydata[key_index].emission_position.y = 0.0f;
        debkeydata[key_index].emission_position.z = 0.0f;
        debkeydata[key_index].momentum.x = 0.0f;
        debkeydata[key_index].momentum.y = 0.0f;
        debkeydata[key_index].momentum.z = 0.0f;
        debkeydata[key_index].emitter_momentum.x = 0.0f;
        debkeydata[key_index].emitter_momentum.y = 0.0f;
        debkeydata[key_index].emitter_momentum.z = 0.0f;
        debkeydata[key_index].portal_room = -1;
        debkeydata[key_index].orientation_flags = 7;
        debkeydata[key_index].gscene = NULL;
        debkeydata[key_index].orientation_dirty = 0.0f;
        debkeydata[key_index].cutoff_distance = 999999.0f;
        debkeydata[key_index].process_collision_sound = 0;
        debkeydata[key_index].last_update_time = now;
        debkeydata[key_index].runtime_created = 1;
        debkeydata[key_index].user_data = NULL;
        debkeydata[key_index].custom_facing = 0;
        if (debkeydata[key_index].emission_end_time < now) {
            debkeydata[key_index].emission_epoch = debkeydata[key_index].emission_end_time;
        } else {
            debkeydata[key_index].emission_epoch = now;
        }
        debkeydata[key_index].emission_disabled = 0;

        switch (effect->particle_type) {
            case DEBRIS_PARTICLE_SUBTRACTIVE:
                debkeydata[key_index].render_priority = 40000;
                break;
            case DEBRIS_PARTICLE_GLASS:
                debkeydata[key_index].render_priority = 20000;
                break;
            case DEBRIS_PARTICLE_MODULATIVE:
                debkeydata[key_index].render_priority = 50000;
                break;
            default:
                debkeydata[key_index].render_priority = 30000;
                break;
        }
        for (i = 0; i < 4; ++i) {
            debkeydata[key_index].collision_timers[i] = 9999;
            if (effect->sound_data[i * 3] != -1) {
                if (effect->sound_data[i * 3 + 1] == 4 || effect->sound_data[i * 3 + 1] == 3) {
                    debkeydata[key_index].collision_timers[i] = 1;
                }
                debkeydata[key_index].process_collision_sound = 1;
            }
        }
        DebrisEmitterPos(key_index, x, y, z);
        DebrisEmitterOrientation(key_index, 0, 0, 0);
        DebrisOrientation(key_index, 0, 0);
        DebrisReflectionOrientation(key_index, 0, 0, 0, 0.9f);
        DebrisSetTrigger(key_index, 0, -1, 0);
        if (newly_allocated) {
            AddDebrisEffectToStack(debkeydata + key_index);
        }
    }

    void AddRotatedDebrisEffect(i32 *handle, i32 effect, f32 x, f32 y, f32 z, i16 rotation_x, i16 rotation_y) {
        AddDebrisEffect(handle, effect, x, y, z);
        DebrisEmitterOrientation(*handle, rotation_x, rotation_y, 0);
    }

    void DebrisPopulateInstance(i32 handle, f32 duration) {
        DEBRISKEY *key;
        DEBRIS_INFO *effect;
        f32 end_time;
        f32 emission_time;
        f32 interval;
        i32 count;
        if (duration < 0.0f || handle == -1) {
            return;
        }
        key = &debkeydata[handle];
        effect = debtab[key->effect_index];
        if (effect->frequency == 0.0) {
            return;
        }
        if (duration == 0.0f) {
            duration = effect->particle_lifetime;
        }
        if (effect->time_group == DEBRIS_DRAW_PANEL) {
            end_time = panelglobaltime + debris_time_increment;
            emission_time = panelglobaltime - duration;
        } else {
            end_time = globaltime + debris_time_increment;
            emission_time = globaltime - duration;
        }
        if (key->previous_allocated_chunk_count == 0) {
            DebReAlloc(key, (i32)(forced_debris_thinning != 0
                                      ? effect->max_particles / debris_thinning_level
                                      : effect->max_particles /
                                            (effect->thinning < debris_thinning_level ? effect->thinning : debris_thinning_level)));
        }
        key->finite = 1;
        if (key->allocated_chunk_count <= 0) {
            return;
        }
        count = 0;
        interval = 1.0f / (forced_debris_thinning != 0
                               ? effect->frequency / debris_thinning_level
                               : effect->frequency / (effect->thinning < debris_thinning_level ? effect->thinning : debris_thinning_level));
        key->emission_epoch = emission_time;
        emission_time += interval;
        while (emission_time < end_time && ++count < 1000) {
            DEBRISPARTICLE *particle = key->generator(key, effect, emission_time);
            if (effect->process_spheres != 0 && particle != NULL) {
                DebrisProcessSpheres(particle, emission_time, effect, key, 0);
            }
            emission_time = interval + key->emission_epoch;
        }
    }

    void DebrisShift(NUMTX *transform) {
        i32 i;
        for (i = 0; i < maxdebkeys; ++i) {
            DEBRISKEY *key = &debkeydata[i];
            DEBRIS_INFO *effect;
            i32 slot;
            i32 found;
            i32 group;
            if (key->effect_index == 0) {
                continue;
            }
            effect = debtab[key->effect_index];
            found = 0;
            for (slot = 0; slot < 8; ++slot) {
                if (i == effect->particle_keys[slot]) {
                    found = 1;
                    break;
                }
            }
            group = effect->time_group == DEBRIS_DRAW_PANEL;
            if (found) {
                if (key->controlled_chunk_count != 0) {
                    i32 chunk;
                    for (chunk = 0; chunk < key->controlled_chunk_count; ++chunk) {
                        DEBRIS_CHUNK_CONTROL *control;
                        for (control = debris_chunk_control_stack[group]; control != NULL; control = control->next) {
                            if (control->particle_chunk == key->particle_chunks[chunk]) {
                                RemoveChunkControlFromStack(control, &debris_chunk_control_stack[group]);
                                freechunkcontrols[--freechunkcontrolsptr] = control;
                                break;
                            }
                        }
                    }
                    key->controlled_chunk_count = 0;
                }
                DebReAlloc(&debkeydata[i], 0);
            } else {
                NuMtxMulR(&debkeydata[i].effect_orientation, transform, &debkeydata[i].effect_orientation);
                NuVecMtxTransform(&debkeydata[i].position, &debkeydata[i].position, transform);
                debkeydata[i].orientation_dirty = 0.0f;
            }
        }
        for (i = 0; i < debrischunks + debrischunksglass; ++i) {
            if (ParticleChunkToRender[i].particle_chunk != NULL && ParticleChunkToRender[i].key == NULL) {
                NuMtxMulR(&ParticleChunkToRender[i].effect_orientation, transform, &ParticleChunkToRender[i].effect_orientation);
                NuVecMtxTransform(&ParticleChunkToRender[i].position, &ParticleChunkToRender[i].position, transform);
            }
        }
    }

    i32 DebrisSuspendDrawObjectSwitch = -1;
    f32 debris_render_scale = 1.0f;
    i32 g_renderingDebris = 0;

    void DebrisDraw(i32 unused, i32 pass) {
        DEBRIS_RENDER_CHUNK *chunk;
        i32 drawn = 0;
        if (debris_suspended != 0) {
            return;
        }
        _NuTimeBarSlotBegin(0, 12, "deb");
        DebMat[7]->texture_id = (i16)debris_rt;
        for (chunk = ParticleChunkRenderStack[pass]; chunk != NULL; chunk = chunk->next) {
            DEBRIS_INFO *effect;
            DEBRISKEY *key;
            NUMTX matrix;
            NUVEC position;
            f32 render_time;
            if (chunk->particle_chunk == NULL) {
                continue;
            }
            effect = chunk->effect;
            key = chunk->key;
            if (DebrisCutSceneMode != 0 && effect->cutscene_only != 0) {
                continue;
            }
            if (DebrisSuspendDrawObjectSwitch != -1 && key != NULL && key->trigger_second == DebrisSuspendDrawObjectSwitch) {
                continue;
            }
            if (effect->native_data == NULL) {
                if (freeDmaDebType == EDPP_MAX_DMADEBTYPES) {
                    DebrisFreeOldestDmaDebTypeTable();
                }
                GenericDebinfoDmaTypeUpdate(effect);
                if (effect->native_data == NULL) {
                    continue;
                }
            }
            if (key != NULL) {
                i32 assigned = 0;
                i32 visible = 1;
                i32 i;
                for (i = 0; i < 8; ++i) {
                    if (effect->particle_keys[i] != -1 && &debkeydata[effect->particle_keys[i]] == key) {
                        assigned = 1;
                        break;
                    }
                }
                if (!assigned && effect->sound_range > 0.0f && effect->use_explicit_clip_box == 0 &&
                    key->cutoff_distance > effect->sound_range) {
                    visible = 0;
                }
                if (key->draw_enabled == 0) {
                    visible = 0;
                }
                if (pass != 4 && visible && effect->generator_type == DEBRIS_GENERATOR_NORMAL && effect->use_explicit_clip_box == 0 &&
                    !assigned) {
                    NUVEC minimum;
                    NUVEC maximum;
                    if (key->clip_radius == 0.0f || *edbits_editor_enabled != 0) {
                        DebrisDrawCalculateClipBoxes(effect, key);
                    }
                    if (edbits_editmode == 0 && key->gscene != NULL && key->portal_room != -1) {
                        if (NuPortalClipTest(key->gscene, &key->position, key->clip_radius, key->portal_room) == 0) {
                            visible = 0;
                        }
                    }
                    minimum = key->clip_min;
                    maximum = key->clip_max;
                    if (NuCameraClipTestExtents(&minimum, &maximum, &key->clip_matrix, 0.0f, 0) == 0) {
                        continue;
                    }
                }
                if (!visible) {
                    continue;
                }
                DebrisMtxCopyPrivate(&matrix, &key->effect_orientation);
                position.x = key->position.x;
                position.y = key->position.y;
                position.z = key->position.z;
            } else {
                if (effect->sound_range > 0.0f && effect->use_explicit_clip_box == 0 &&
                    CameraEmitterDistance(&chunk->position) > effect->sound_range) {
                    continue;
                }
                matrix = chunk->effect_orientation;
                position.x = chunk->position.x;
                position.y = chunk->position.y;
                position.z = chunk->position.z;
            }
            drawn = 1;
            NuMtxTranslate(&matrix, &position);
            if (pass == 4) {
                NuMtxMulVU0(&matrix, &matrix, NuCameraGetMtx());
                render_time = debris_render_panel_time;
                effect->last_render_time = panelglobaltime;
            } else {
                render_time = debris_render_global_time;
                effect->last_render_time = globaltime;
            }
            if (key != NULL && key->custom_facing != 0) {
                NuRndrSetParticleRotation(&key->particle_orientation);
            } else if (effect->camera_facing != 0) {
                NuRndrSetParticleRotation(&xzfacingmtx);
            } else {
                NuRndrSetParticleRotation(NULL);
            }
            NuMtxPreScaleX(&matrix, debris_render_scale);
            if (effect->particle_type == DEBRIS_PARTICLE_GLASS) {
                NuRndrParticleGroup(chunk->particle_chunk, chunk->effect->native_data, DebMat[chunk->effect->particle_type], render_time,
                                    &matrix, 4, effect->particle_parameter_a, effect->particle_parameter_b, effect->clip_extent,
                                    effect->camera_cutoff_radius);
            } else if (effect->use_explicit_clip_box != 0) {
                NuRndrSetDebBox(&effect->particle_box);
                NuRndrParticleGroup(chunk->particle_chunk, chunk->effect->native_data, DebMat[chunk->effect->particle_type], render_time,
                                    &matrix, 6, effect->particle_parameter_a, effect->particle_parameter_b, effect->clip_extent,
                                    effect->camera_cutoff_radius);
            } else {
                NuRndrParticleGroup(chunk->particle_chunk, chunk->effect->native_data, DebMat[chunk->effect->particle_type], render_time,
                                    &matrix, 0, effect->particle_parameter_a, effect->particle_parameter_b, effect->clip_extent,
                                    effect->camera_cutoff_radius);
            }
        }
        if (drawn != 0) {
            g_renderingDebris = g_renderingDebris == 0;
        }
        _NuTimeBarSlotEnd(0, 12);
    }

    u8 debris_object_switches[128] = {0};

    void DebrisProcessTriggers(void) {
        i32 last_switch_change;
        DEBRIS_INFO *effect;
        DEBRISKEY *next;
        f32 shift;
        f32 range;
        f32 volume;
        DEBRISKEY *key;
        i32 i;
        i32 switch_changes[32][2];
        last_switch_change = -1;
        for (key = debris_keystack; key != NULL; key = next) {
            next = key->previous;
            effect = debtab[key->effect_index];
            switch (key->trigger_first) {
                case 1:
                    if (key->finite == 2) {
                        continue;
                    }
                    if (key->trigger_second != -1) {
                        switch (debris_object_switches[key->trigger_second]) {
                            case 0:
                                key->finite = 0;
                                break;
                            case 1:
                                key->finite = 1;
                                break;
                            case 2:
                                last_switch_change = (last_switch_change + 1) & 31;
                                switch_changes[last_switch_change][1] = 3;
                                key->finite = 2;
                                switch_changes[last_switch_change][0] = key->trigger_second;
                                break;
                            case 3:
                                last_switch_change = (last_switch_change + 1) & 31;
                                switch_changes[last_switch_change][1] = 0;
                                switch_changes[last_switch_change][0] = key->trigger_second;
                                break;
                            case 4:
                                last_switch_change = (last_switch_change + 1) & 31;
                                switch_changes[last_switch_change][1] = 0;
                                key->finite = 2;
                                switch_changes[last_switch_change][0] = key->trigger_second;
                                break;
                        }
                    }
                    if (key->finite != 2) {
                        continue;
                    }
                    DebrisStartOffsetEx(key, 0.0f);
                    key->emission_disabled = 0;
                    shift = key->emission_time - globaltime;
                    key->emission_time -= shift;
                    key->emission_end_time -= shift;
                    key->emission_epoch = globaltime;
                    if (key->process_collision_sound == 0) {
                        continue;
                    }
                    volume = 0.0f;
                    key->cutoff_distance = CameraEmitterDistance(&key->position);
                    range = effect->sound_range_override == 0.0f ? (effect->sound_range == 0.0f ? effect->clip_extent : effect->sound_range)
                                                                 : effect->sound_range_override;
                    if (range > key->cutoff_distance) {
                        for (i = 0; i < 4; ++i) {
                            if (effect->sound_data[i * 3] != -1) {
                                SetSfxBit_On(effect->sound_data[i * 3]);
                            }
                        }
                        volume = (range - key->cutoff_distance) / range;
                    }
                    if (range > key->cutoff_distance) {
                        {
                            i32 sound_index;
                            for (sound_index = 0; sound_index < 4; ++sound_index) {
                                if (effect->sound_data[sound_index * 3] != -1 && effect->sound_data[sound_index * 3 + 1] == 1) {
                                    PlaySfxByIdEx(effect->sound_data[sound_index * 3], &key->position, volume, 1.0f);
                                }
                            }
                        }
                    }
                    break;
            }
        }
        for (i = 0; i <= last_switch_change; ++i) {
            debris_object_switches[switch_changes[i][0]] = (u8)switch_changes[i][1];
        }
    }

    void DebrisProcessAllocation(void) {
        DEBRISKEY *key = debris_keystack;
        while (key != NULL) {
            DEBRISKEY *next = key->previous;
            if (key->previous_particle_count != key->particle_count) {
                DebReAlloc2(key);
            }
            key = next;
        }
    }

    void DebrisProcessGeneration(void) {
        DEBRISKEY *next;
        DEBRIS_INFO *effect;
        f32 now;
        f32 sound_range;
        f32 volume;
        f32 emission_interval;
        f32 emission_time;
        f32 pause;
        i32 transitions;
        DEBRISPARTICLE *particle;
        DEBRISKEY *key;
        i32 i;
        i32 emission;
        i32 handle;
        for (key = debris_keystack; key != NULL; key = next) {
            pause = 0.0f;
            emission_interval = 0.0f;
            volume = 1.0f;
            emission = 0;
            next = key->previous;
            effect = debtab[key->effect_index];
            now = effect->time_group == DEBRIS_DRAW_PANEL ? panelglobaltime : globaltime;
            if (key->emission_disabled != 0) {
                continue;
            }
            key->cutoff_distance = CameraEmitterDistance(&key->position);
            if (key->finite != 0) {
                if (key->cutoff_distance < effect->cut_on || (effect->clip_extent > 0.0f && effect->clip_extent < key->cutoff_distance)) {
                    if (effect->use_explicit_clip_box == 0 && effect->time_group != DEBRIS_DRAW_PANEL) {
                        key->finite = 0;
                    }
                }
                if (debris_render_group != 0 && key->render_group != 0 && key->render_group != debris_render_group) {
                    key->finite = 0;
                }
                if (((i8)key->orientation_flags & debris_detail_level) == 0) {
                    key->finite = 0;
                }
            }
            sound_range = effect->sound_range_override == 0.0f ? (effect->sound_range == 0.0f ? effect->clip_extent : effect->sound_range)
                                                               : effect->sound_range_override;
            if (sound_range > key->cutoff_distance) {
                for (i = 0; i < 4; ++i) {
                    if (effect->sound_data[i * 3] != -1) {
                        {
                            i32 sample_id;
                            i32 word;
                            if ((effect->sound_data[i * 3]) >= 0) {
                                sample_id = (i32)(SfxInfo[(effect->sound_data[i * 3])].sample_id_flags << 17) >> 17;
                                if ((u32)sample_id <= 0x63f) {
                                    word = sample_id / 16;
                                    if (word < 100) {
                                        SfxBits[word] |= (u16)(1 << (sample_id & 0xf));
                                    }
                                }
                            }
                        }
                    }
                }
                volume = (sound_range - key->cutoff_distance) / sound_range;
            }
            if (key->process_collision_sound != 0 && key->finite != 0 && sound_range > key->cutoff_distance) {
                {
                    i32 sound_index;
                    for (sound_index = 0; sound_index < 4; ++sound_index) {
                        if (effect->sound_data[sound_index * 3] != -1 && effect->sound_data[sound_index * 3 + 1] == 4) {
                            PlaySfxByIdEx(effect->sound_data[sound_index * 3], &key->position, volume, 1.0f);
                        }
                    }
                }
            }
            if (effect->status == 0) {
                key->finite = 0;
            }
            if (effect->status == 2) {
                key->finite = 1;
            }
            if (key->status == 0) {
                key->finite = 0;
            }
            if (key->status == 2) {
                key->finite = 1;
            }
            if (key->finite != 0 && key->previous_allocated_chunk_count == 0) {
                DebReAlloc(key, effect->max_particles);
                DebReAlloc(key, (i32)(forced_debris_thinning != 0
                                          ? effect->max_particles / debris_thinning_level
                                          : effect->max_particles /
                                                (effect->thinning < debris_thinning_level ? effect->thinning : debris_thinning_level)));
            }
            key->emission_position.x = key->emitter_momentum.x * (now - key->last_update_time);
            key->emission_position.y = key->emitter_momentum.y * (now - key->last_update_time);
            key->emission_position.z = key->emitter_momentum.z * (now - key->last_update_time);
            if ((f32)effect->frequency > 0.0f) {
                emission_interval =
                    1.0f /
                    (forced_debris_thinning != 0
                         ? (f32)effect->frequency / debris_thinning_level
                         : (f32)effect->frequency / (effect->thinning < debris_thinning_level ? effect->thinning : debris_thinning_level));
            }
            emission_time = emission_interval + key->emission_epoch;
            while (emission_time < now + debris_time_increment && ++emission < 100) {
                transitions = 0;
                while (emission_time >= key->emission_end_time && key->emission_time <= emission_time && ++transitions < 100) {
                    pause = 0.0f;
                    if (key->emission_time >= key->emission_end_time) {
                        key->emission_end_time =
                            effect->emission_period + key->emission_time + NuRandFloatSeeded(&debrisseed) * effect->emission_period_random;
                        if (key->finite_count > 0) {
                            if (--key->finite_count == 0) {
                                handle = key->allocation_index;
                                DebFree(&handle);
                                key->process_collision_sound = 0;
                                emission_time = (f32)((f64)emission_time + 99999.0);
                            }
                        }
                        if (key->finite_count < 0 && ++key->finite_count == 0) {
                            key->status = 0;
                            key->finite = 0;
                        }
                        if (key->process_collision_sound != 0 && key->finite != 0 && key->cutoff_distance < sound_range) {
                            {
                                i32 sound_index;
                                for (sound_index = 0; sound_index < 4; ++sound_index) {
                                    if (effect->sound_data[sound_index * 3] != -1 && effect->sound_data[sound_index * 3 + 1] == 1) {
                                        PlaySfxByIdEx(effect->sound_data[sound_index * 3], &key->position, volume, 1.0f);
                                    }
                                }
                            }
                        }
                    } else {
                        key->previous_emission_time = key->emission_time;
                        pause = effect->emission_pause + NuRandFloatSeeded(&debrisseed) * effect->emission_pause_random;
                        key->emission_time = pause + key->emission_end_time;
                        if (key->finite == 2) {
                            key->finite = 0;
                        }
                        if (key->process_collision_sound != 0 && key->finite != 0 && key->cutoff_distance < sound_range) {
                            {
                                i32 sound_index;
                                for (sound_index = 0; sound_index < 4; ++sound_index) {
                                    if (effect->sound_data[sound_index * 3] != -1 && effect->sound_data[sound_index * 3 + 1] == 2) {
                                        PlaySfxByIdEx(effect->sound_data[sound_index * 3], &key->position, volume, 1.0f);
                                    }
                                }
                            }
                        }
                    }
                }
                if (pause > 0.0f) {
                    emission_time = key->emission_time - emission_interval;
                } else if (key->allocated_chunk_count > 0 && key->finite != 0) {
                    particle = key->generator(key, effect, emission_time);
                    if (effect->process_spheres != 0 && emission == 1 && particle != NULL) {
                        DebrisProcessSpheres(particle, emission_time, effect, key, 0);
                    }
                    if (key->process_collision_sound != 0 && key->cutoff_distance < sound_range) {
                        {
                            i32 sound_index;
                            for (sound_index = 0; sound_index < 4; ++sound_index) {
                                if (effect->sound_data[sound_index * 3] != -1 && effect->sound_data[sound_index * 3 + 1] == 3) {
                                    PlaySfxByIdEx(effect->sound_data[sound_index * 3], &key->position, volume, 1.0f);
                                }
                            }
                        }
                    }
                }
                key->emission_epoch = emission_time;
                emission_time += emission_interval;
            }
            if (key->finite == 0) {
                if (key->status != 0 && key->trigger_second == -1 && key->cutoff_distance >= effect->cut_on &&
                    (effect->clip_extent == 0.0f || key->cutoff_distance <= effect->clip_extent) &&
                    (debris_render_group == 0 || key->render_group == 0 || key->render_group == debris_render_group) &&
                    ((i8)key->orientation_flags & debris_detail_level) != 0) {
                    key->finite = 1;
                }
                if (key->finite == 0 && key->previous_allocated_chunk_count != 0) {
                    DebReAlloc(key, 0);
                }
            }
        }
    }

    i32 DebrisPreCheckCollisions(NUVEC *position, f32 radius) {
        DEBRISKEY *key = debris_keystack;
        numspherecolldata = 0;
        numtoruscolldata = 0;
        while (key != NULL) {
            i32 effect_index = key->effect_index;
            i32 key_index = key->allocation_index;
            DEBRISKEY *previous = key->previous;
            if (debtab[effect_index] == NULL) {
                DebFreeInstantly(&key_index);
                key->allocation_index = -1;
            }
            if (key->finite != 0) {
                if (DebrisSingleCollisionCheckScaleYFlag(key_index, position, radius, 1.0f, 3) != 0) {
                    spherecolldata[numspherecolldata].key_index = key_index;
                    spherecolldata[numspherecolldata++].flags = debtab[effect_index]->collision_flags;
                }
                if (DebrisSingleTorusCollisionCheckScaleYFlag(key_index, position, radius, 1.0f, 3) != 0) {
                    toruscolldata[numtoruscolldata].key_index = key_index;
                    toruscolldata[numtoruscolldata++].flags = debtab[effect_index]->collision_flags;
                }
            }
            key = previous;
        }
        return numspherecolldata + numtoruscolldata;
    }

    void DebrisDrawGlassEx(i32 flicker) {
        i32 reserved;
        if (DebrisGlassInitialized == 0) {
            return;
        }
        reserved = NuTexReserve(NuTexGetReqSize(debris_rt, 0));
        NuRndrBeginSceneEx(1, 2, 1);
        if (freedebchkptrg > 0) {
            DebrisDraw(0, 2);
        }
        NuRainDraw(reserved);
        NuRndrEndScene();
        NuTexUnReserve();
    }

    void DebrisDrawGlass(void) {
        i32 reserved;
        if (DebrisGlassInitialized == 0) {
            return;
        }
        reserved = NuTexReserve(NuTexGetReqSize(debris_rt, 0));
        NuRndrBeginSceneEx(1, 2, 1);
        if (freedebchkptrg > 0) {
            DebrisDraw(0, 2);
        }
        NuRainDraw(reserved);
        NuRndrEndScene();
        NuTexUnReserve();
    }

    /* Float fabs by clearing the sign bit. */
    static f32 EdAnimFabs(f32 value) {
        f32 result;
        *(u32 *)&result = *(u32 *)&value & 0x7fffffff;
        return result;
    }

    i32 EdAnimLocalFrameCount = 0;
    i32 edanim_sound_mode = 0;

    void edanimUpdateObjects(f32 elapsed) {
        NUINSTANIM *animation;
        nuhspecial_s special;
        f32 seconds;
        NUMTX orientation;
        i32 index;
        i32 particle_index;
        i32 sound_index;
        i32 play;
        seconds = NuVideoGetMode() == 3 ? elapsed / 50.0f : elapsed / 60.0f;
        for (index = 0; index < 64; ++index) {
            if (AnimParams[index].instance_id == -1 || edanim_page_on[AnimParams[index].page] == 0) {
                continue;
            }
            animation = NULL;
            if (edanim_page_scene[AnimParams[index].page] != NULL) {
                NuGScnGetSpecial(&special, edanim_page_scene[AnimParams[index].page], AnimParams[index].instance_id);
                animation = (NUINSTANIM *)NuSpecialGetInstAnim(&special);
                NuSpecialGetInstanceix(&special);
            }
            if (animation != NULL) {
                switch (AnimParams[index].control_mode) {
                    case EDANIM_CONTROL_SWITCH:
                        animation->flags &= ~NUINSTANIM_FLAG_PLAYING;
                        if (AnimParams[index].control_switch != -1 && debris_object_switches[AnimParams[index].control_switch] != 0) {
                            animation->flags |= NUINSTANIM_FLAG_PLAYING;
                        }
                        break;
                    case EDANIM_CONTROL_SWITCH_ONE_CYCLE:
                        animation->flags &= ~NUINSTANIM_FLAG_REPEATING;
                        if (AnimParams[index].control_switch != -1 && debris_object_switches[AnimParams[index].control_switch] != 0 &&
                            (animation->flags & NUINSTANIM_FLAG_PLAYING) == 0) {
                            animation->ltime = 1.0f;
                            animation->flags = (animation->flags & ~6U) | NUINSTANIM_FLAG_PLAYING;
                        }
                        break;
                    case EDANIM_CONTROL_SWITCH_CONTINUOUS:
                        animation->flags |= NUINSTANIM_FLAG_REPEATING;
                        if (AnimParams[index].control_switch != -1 && debris_object_switches[AnimParams[index].control_switch] != 0) {
                            animation->flags |= NUINSTANIM_FLAG_PLAYING;
                        }
                        break;
                    case EDANIM_CONTROL_PROXIMITY:
                        if (edanimPlayerAnimDistance(index) < AnimParams[index].control_distance) {
                            animation->flags |= NUINSTANIM_FLAG_PLAYING;
                        } else {
                            animation->flags &= ~NUINSTANIM_FLAG_PLAYING;
                        }
                        break;
                    case EDANIM_CONTROL_PROXIMITY_ONE_CYCLE:
                        animation->flags &= ~NUINSTANIM_FLAG_REPEATING;
                        if (edanimPlayerAnimDistance(index) < AnimParams[index].control_distance &&
                            (animation->flags & NUINSTANIM_FLAG_PLAYING) == 0) {
                            animation->ltime = 1.0f;
                            animation->flags = (animation->flags & ~6U) | NUINSTANIM_FLAG_PLAYING;
                        }
                        break;
                    case EDANIM_CONTROL_PROXIMITY_CONTINUOUS:
                        animation->flags |= NUINSTANIM_FLAG_REPEATING;
                        if (edanimPlayerAnimDistance(index) < AnimParams[index].control_distance) {
                            animation->flags |= NUINSTANIM_FLAG_PLAYING;
                        }
                        break;
                    case EDANIM_CONTROL_OVERRIDE_NO_ANIM:
                        animation->ltime = 1.0f;
                        animation->flags &= ~NUINSTANIM_FLAG_PLAYING;
                        break;
                    case EDANIM_CONTROL_OVERRIDE_PLAY:
                        animation->flags |= NUINSTANIM_FLAG_PLAYING;
                        break;
                    case EDANIM_CONTROL_OVERRIDE_PLAY_CONTINUOUS:
                        animation->flags |= NUINSTANIM_FLAG_PLAYING | NUINSTANIM_FLAG_REPEATING;
                        break;
                }
                if (index == edanim_nearest_param_id && (edanim_particle_mode != 0 || edanim_sound_mode != 0)) {
                    animation->ltime = 1.0f;
                }
            }
            if (NuSpecialGetVisibilityFn(&special) != 0) {
                for (particle_index = 0; particle_index < AnimParams[index].effect_count; ++particle_index) {
                    if (AnimParams[index].effect_ids[particle_index] != -1 &&
                        debtab[AnimParams[index].effect_ids[particle_index]] != NULL) {
                        if (AnimParams[index].effect_flags[particle_index] == 0 ||
                            (animation != NULL && (animation->flags & NUINSTANIM_FLAG_PLAYING) != 0)) {
                            NUMTX matrix;
                            NUVEC position;
                            NuMtxInvRSS(&matrix, NuSpecialGetMtx(&special));
                            NuMtxMul(&matrix, &matrix, NuSpecialGetDrawMtx(&special));
                            position = *(NUVEC *)AnimParams[index].effect_positions[particle_index];
                            NuVecMtxTransform(&position, &position, &matrix);
                            orientation = NuMtxSetIdentityTemplate;
                            NuMtxRotateZ(&orientation, AnimParams[index].effect_angles[particle_index]);
                            NuMtxRotateY(&orientation, AnimParams[index].effect_angle_ranges[particle_index]);
                            NuMtxMul(&matrix, &orientation, &matrix);
                            AddVariableShotDebrisEffectTimed3(AnimParams[index].effect_ids[particle_index], &position,
                                                              &APIObjectZeroMomentumPC, AnimParams[index].effect_intervals[particle_index],
                                                              seconds, &matrix, &NuMtxSetIdentityTemplate);
                        }
                    } else if (AnimParams[index].effect_names[particle_index][0] != 0) {
                        AnimParams[index].effect_ids[particle_index] =
                            LookupDebrisEffectPageIgnore(AnimParams[index].effect_names[particle_index], 0, 0);
                        if (AnimParams[index].effect_ids[particle_index] == -1) {
                            edanimParticleDestroy(index, particle_index);
                            --particle_index;
                        }
                    }
                }
                for (sound_index = 0; sound_index < AnimParams[index].sound_count; ++sound_index) {
                    if (AnimParams[index].sound_ids[sound_index] != -1) {
                        play = -1;
                        if (AnimParams[index].sound_flags[sound_index] == 1) {
                            if ((i32)((f64)EdAnimLocalFrameCount + (f64)elapsed) / (i32)AnimParams[index].sound_values[sound_index] >
                                EdAnimLocalFrameCount / (i32)AnimParams[index].sound_values[sound_index]) {
                                play = AnimParams[index].sound_ids[sound_index];
                            }
                        } else if (animation != NULL) {
                            if (animation->ltime >= AnimParams[index].sound_values[sound_index] &&
                                AnimParams[index].sound_values[sound_index] > AnimParams[index].previous_time) {
                                play = AnimParams[index].sound_ids[sound_index];
                            }
                            if ((animation->flags & 0x10) != 0 && animation->ltime <= AnimParams[index].sound_values[sound_index] &&
                                AnimParams[index].sound_values[sound_index] < EdAnimFabs(AnimParams[index].previous_time)) {
                                play = AnimParams[index].sound_ids[sound_index];
                            }
                        }
                        if (play != -1) {
                            NUMTX matrix;
                            NUVEC position;
                            NuMtxInvRSS(&matrix, NuSpecialGetMtx(&special));
                            NuMtxMul(&matrix, &matrix, NuSpecialGetDrawMtx(&special));
                            /* Uses the completed particle-loop index here. */
                            position = AnimParams[index].sound_positions[particle_index];
                            NuVecMtxTransform(&position, &position, &matrix);
                        }
                    } else if (AnimParams[index].sound_names[sound_index][0] != 0) {
                        AnimParams[index].sound_ids[sound_index] = -1;
                        edanimSoundDestroy(index, sound_index);
                        --sound_index;
                    }
                }
            }
            if (animation != NULL) {
                if ((animation->flags & 0x10) != 0) {
                    AnimParams[index].previous_time = -animation->ltime;
                } else {
                    AnimParams[index].previous_time = animation->ltime;
                }
            }
        }
        EdAnimLocalFrameCount += (i32)elapsed;
    }

    i32 edbits_anim_page = 0;

    i32 edanimParamCreate(i32 instance_id) {
        i32 start;
        i32 index;
        nuhspecial_s special;
        if (edanim_params_used == 64) {
            return -1;
        }
        index = edanim_next_param;
        start = index;
        if (AnimParams[index].instance_id != -1) {
            do {
                if (++index > 64) {
                    index = 0;
                }
                if (index == start) {
                    edanim_next_param = index;
                    return -1;
                }
            } while (AnimParams[index].instance_id != -1);
            edanim_next_param = index;
        }
        AnimParams[index].instance_id = instance_id;
        AnimParams[index].effect_count = 0;
        NuGScnGetSpecial(&special, edbits_base_scene, instance_id);
        AnimParams[edanim_next_param].platform_id = FindPlatInst(NuSpecialGetInstanceix(&special));
        AnimParams[edanim_next_param].bounce_impulse = 0.0f;
        AnimParams[edanim_next_param].bounce_spring = 0.0f;
        AnimParams[edanim_next_param].bounce_damping = 0.0f;
        if (AnimParams[edanim_next_param].platform_id != -1) {
            PlatInstBounce(AnimParams[edanim_next_param].platform_id, AnimParams[edanim_next_param].bounce_impulse,
                           AnimParams[edanim_next_param].bounce_spring, AnimParams[edanim_next_param].bounce_damping);
        }
        AnimParams[edanim_next_param].page = (i8)edbits_anim_page;
        edanim_page_used[edbits_anim_page] = 1;
        edanim_page_on[edbits_anim_page] = 1;
        if (!edanim_page_scene[edbits_anim_page]) {
            edanim_page_scene[edbits_anim_page] = edbits_base_scene;
        }
        index = edanim_next_param++;
        ++edanim_params_used;
        return index;
    }

    void edanimSoundCreate(NUVEC *position) {
        i32 index = AnimParams[edanim_nearest_param_id].sound_count;
        if (index != 8 && edanim_sound_type != -1) {
            edanimSoundPlace(index, position);
            AnimParams[edanim_nearest_param_id].sound_ids[index] = edanim_sound_type;
            AnimParams[edanim_nearest_param_id].sound_flags[index] = 1;
            strcpy(AnimParams[edanim_nearest_param_id].sound_names[index], NULL);
            AnimParams[edanim_nearest_param_id].sound_values[index] = 50.0f;
            ++AnimParams[edanim_nearest_param_id].sound_count;
        }
    }

    i32 edanim_cam_ax = 0;
    i32 edanim_cam_ay = 0;

    void edanimDoInput(FRAME_PAD *pad) {
        nuhspecial_s special;
        NUVEC position;
        NUVEC *origin;
        i32 index;
        i32 effect;
        if ((pad->digital_buttons & PAD_BUTTON_SELECT) == 0) {
            edcamMove(pad);
        }
        if (pad->digital_buttons & PAD_BUTTON_SELECT) {
            if (edanim_sound_mode == 0 && (pad->digital_buttons_pressed & PAD_BUTTON_SQUARE)) {
                if (edanim_particle_mode) {
                    edanim_particle_mode = 0;
                } else if (edanim_nearest != -1 && edanim_nearest_param_id != -1) {
                    edanim_particle_mode = 1;
                    edanim_nearest_particle = -1;
                }
            }
            if (edanim_particle_mode) {
                if (edanim_nearest_particle != -1) {
                    if (pad->digital_buttons_pressed & PAD_BUTTON_R1) {
                        if (++edanim_nearest_particle == AnimParams[edanim_nearest_param_id].effect_count) {
                            edanim_nearest_particle = 0;
                        }
                    }
                    if (pad->digital_buttons_pressed & PAD_BUTTON_R2) {
                        if (--edanim_nearest_particle == -1) {
                            edanim_nearest_particle = AnimParams[edanim_nearest_param_id].effect_count - 1;
                        }
                    }
                } else {
                    edanimDetermineNearestParticle(-1.0f);
                }
                if (edanim_nearest_particle != -1) {
                    NuGScnGetSpecial(&special, edbits_base_scene, edanim_nearest);
                    origin = NuSpecialGetPos(&special);
                    NuVecAdd(&position, origin, (NUVEC *)AnimParams[edanim_nearest_param_id].effect_positions[edanim_nearest_particle]);
                    edcamSetPos(&position);
                    edanim_emitrotz = AnimParams[edanim_nearest_param_id].effect_angles[edanim_nearest_particle];
                    edanim_emitroty = AnimParams[edanim_nearest_param_id].effect_angle_ranges[edanim_nearest_particle];
                    edanim_particle_type = AnimParams[edanim_nearest_param_id].effect_ids[edanim_nearest_particle];
                }
            } else {
                if (pad->digital_buttons_pressed & PAD_BUTTON_TRIANGLE) {
                    if (edanim_sound_mode) {
                        edanim_sound_mode = 0;
                    } else if (edanim_nearest != -1 && edanim_nearest_param_id != -1) {
                        edanim_sound_mode = 1;
                        edanim_nearest_sound = -1;
                    }
                }
                if (edanim_sound_mode) {
                    if (edanim_nearest_sound != -1) {
                        if (pad->digital_buttons_pressed & PAD_BUTTON_R1) {
                            if (++edanim_nearest_sound == AnimParams[edanim_nearest_param_id].sound_count) {
                                edanim_nearest_sound = 0;
                            }
                        }
                        if (pad->digital_buttons_pressed & PAD_BUTTON_R2) {
                            if (--edanim_nearest_sound == -1) {
                                edanim_nearest_sound = AnimParams[edanim_nearest_param_id].sound_count - 1;
                            }
                        }
                    } else {
                        edanimDetermineNearestSound(-1.0f);
                    }
                    if (edanim_nearest_sound != -1) {
                        NuGScnGetSpecial(&special, edbits_base_scene, edanim_nearest);
                        origin = NuSpecialGetPos(&special);
                        NuVecAdd(&position, origin, &AnimParams[edanim_nearest_param_id].sound_positions[edanim_nearest_sound]);
                        edcamSetPos(&position);
                        edanim_sound_type = AnimParams[edanim_nearest_param_id].sound_ids[edanim_nearest_sound];
                    }
                } else {
                    if (edanim_nearest != -1) {
                        if (pad->digital_buttons_pressed & PAD_BUTTON_R1) {
                            if (++edanim_nearest == NuGScnNumSpecials(edbits_base_scene)) {
                                edanim_nearest = 0;
                            }
                        }
                        if (pad->digital_buttons_pressed & PAD_BUTTON_R2) {
                            if (--edanim_nearest == -1) {
                                edanim_nearest = NuGScnNumSpecials(edbits_base_scene) - 1;
                            }
                        }
                    } else {
                        edanimDetermineNearestAnim(-1.0f);
                    }
                    if (edanim_nearest != -1) {
                        NuGScnGetSpecial(&special, edbits_base_scene, edanim_nearest);
                        edcamSetPos(NuSpecialGetPos(&special));
                        edanim_nearest_param_id = -1;
                        for (index = 0; index < 64; ++index) {
                            if (AnimParams[index].instance_id == edanim_nearest) {
                                edanim_nearest_param_id = index;
                                break;
                            }
                        }
                    }
                }
            }
        }
        if (edanim_nearest_param_id != -1) {
            for (effect = 0; effect < AnimParams[edanim_nearest_param_id].effect_count; ++effect) {
                if ((AnimParams[edanim_nearest_param_id].effect_ids[effect] == -1 ||
                     !debtab[AnimParams[edanim_nearest_param_id].effect_ids[effect]]) &&
                    AnimParams[edanim_nearest_param_id].effect_names[effect][0]) {
                    AnimParams[edanim_nearest_param_id].effect_ids[effect] =
                        LookupDebrisEffectPageIgnore(AnimParams[edanim_nearest_param_id].effect_names[effect], 0, 0);
                    if (AnimParams[edanim_nearest_param_id].effect_ids[effect] == -1) {
                        edanimParticleDestroy(edanim_nearest_param_id, effect);
                        --effect;
                    }
                }
            }
        }
        edcamGetPosAng(&edanim_cam_pos, &edanim_cam_ax, &edanim_cam_ay);
        if ((pad->digital_buttons & PAD_BUTTON_SELECT) == 0) {
            if (pad->digital_buttons_pressed & PAD_BUTTON_SQUARE) {
                edanim_active_menu = edanim_options_menu;
            }
            if (pad->digital_buttons_pressed & PAD_BUTTON_CROSS) {
                if (edanim_particle_mode) {
                    edanimParticleCreate(&edanim_cam_pos);
                } else if (edanim_sound_mode) {
                    edanimSoundCreate(&edanim_cam_pos);
                } else if (edanim_nearest != -1 && edanim_nearest_param_id == -1) {
                    edanim_nearest_param_id = edanimParamCreate(edanim_nearest);
                }
            }
            if (pad->digital_buttons & PAD_BUTTON_CIRCLE) {
                if (edanim_particle_mode) {
                    if (edanim_nearest_particle != -1) {
                        edanimParticlePlace(edanim_nearest_particle, &edanim_cam_pos);
                    }
                } else if (edanim_sound_mode && edanim_nearest_sound != -1) {
                    edanimSoundPlace(edanim_nearest_sound, &edanim_cam_pos);
                }
            }
            if (pad->digital_buttons_pressed & PAD_BUTTON_TRIANGLE) {
                if (edanim_particle_mode) {
                    if (edanim_nearest_particle != -1) {
                        edanimParticleDestroy(edanim_nearest_param_id, edanim_nearest_particle);
                        edanim_nearest_particle = -1;
                    }
                } else if (edanim_sound_mode) {
                    if (edanim_nearest_sound != -1) {
                        edanimSoundDestroy(edanim_nearest_param_id, edanim_nearest_sound);
                        edanim_nearest_sound = -1;
                    }
                } else {
                    if (edanim_nearest_param_id != -1) {
                        if (AnimParams[edanim_nearest_param_id].instance_id != -1) {
                            AnimParams[edanim_nearest_param_id].instance_id = -1;
                        }
                        --edanim_params_used;
                    }
                    edanim_nearest_param_id = -1;
                    edanim_nearest = -1;
                    return;
                }
            }
        }
        if (edanim_particle_mode) {
            edanim_emitroty += pad->analog_left_pad_right;
            edanim_emitroty -= pad->analog_left_pad_left;
            edanim_emitrotz += pad->analog_left_pad_up;
            if (edanim_emitrotz > 0) {
                edanim_emitrotz = 0;
            }
            edanim_emitrotz -= pad->analog_left_pad_down;
            if (edanim_emitrotz < -0x8000) {
                edanim_emitrotz = -0x8000;
            }
        }
    }

    i32 edanimLoadPage(char *path, NUGSCN *scene) {
        i32 page;
        i32 version;
        i32 count;
        i32 slot;
        i32 index;
        i32 item;
        i32 extra;
        i32 interval;
        i32 instance;
        f32 impulse;
        f32 spring;
        f32 damping;
        char name[20];
        char discarded_name[16];
        NUVEC discarded_position;
        nuhspecial_s special;
        TERRAIN_SET *terrain;
        TERRAIN_PLATFORM *platform;
        page = -1;
        for (index = 0; index < 8; ++index) {
            if (!edanim_page_used[index]) {
                page = index;
                break;
            }
        }
        if (page == -1) {
            return -1;
        }
        EdFileSetMedia(1);
        if (!EdFileOpen(path, 0)) {
            return -1;
        }
        EdFileSetReadWrongEndianess(1);
        version = EdFileReadInt();
        if (version > 6) {
            EdFileSetReadWrongEndianess(0);
            EdFileClose();
            return -1;
        }
        count = EdFileReadInt();
        if (count + edanim_params_used > 64) {
            count = 64 - edanim_params_used;
        }
        slot = 0;
        for (index = 0; index < count; ++index) {
            while (AnimParams[slot].instance_id != -1 && slot < 64) {
                ++slot;
            }
            if (slot >= 64) {
                continue;
            }
            EdFileRead(name, 20);
            AnimParams[slot].instance_id = edanimLookupSpecial(name, scene);
            AnimParams[slot].effect_count = EdFileReadInt();
            if (version >= 2) {
                AnimParams[slot].sound_count = EdFileReadInt();
            } else {
                AnimParams[slot].sound_count = 0;
            }
            AnimParams[slot].control_mode = EdFileReadInt();
            AnimParams[slot].control_switch = EdFileReadInt();
            AnimParams[slot].control_distance = EdFileReadFloat();
            AnimParams[slot].switch_delay = EdFileReadFloat();
            extra = 0;
            if (AnimParams[slot].effect_count > 8) {
                extra = 8 - AnimParams[slot].effect_count;
                AnimParams[slot].effect_count = 8;
            }
            for (item = 0; item < AnimParams[slot].effect_count; ++item) {
                EdFileRead(AnimParams[slot].effect_names[item], 16);
                AnimParams[slot].effect_ids[item] = -1;
                if (version < 5) {
                    interval = EdFileReadInt();
                    if (interval > 0) {
                        AnimParams[slot].effect_intervals[item] = interval * 60;
                    } else if (interval < 0) {
                        AnimParams[slot].effect_intervals[item] = -60 / interval;
                    } else {
                        AnimParams[slot].effect_intervals[item] = 0;
                    }
                } else {
                    AnimParams[slot].effect_intervals[item] = version == 5 ? (i32)EdFileReadFloat() : EdFileReadInt();
                }
                AnimParams[slot].effect_flags[item] = EdFileReadInt();
                EdFileReadNuVec((NUVEC *)AnimParams[slot].effect_positions[item]);
                if (version >= 3) {
                    AnimParams[slot].effect_angles[item] = EdFileReadShort();
                    AnimParams[slot].effect_angle_ranges[item] = EdFileReadShort();
                } else {
                    AnimParams[slot].effect_angles[item] = 0;
                    AnimParams[slot].effect_angle_ranges[item] = 0;
                }
            }
            for (item = 0; item < extra; ++item) {
                EdFileRead(discarded_name, 16);
                EdFileReadInt();
                EdFileReadInt();
                EdFileReadNuVec(&discarded_position);
                if (version >= 3) {
                    EdFileReadShort();
                    EdFileReadShort();
                }
            }
            AnimParams[slot].previous_time = 0.99f;
            extra = 0;
            if (version >= 2) {
                if (AnimParams[slot].sound_count > 8) {
                    extra = 8 - AnimParams[slot].sound_count;
                    AnimParams[slot].sound_count = 8;
                }
                for (item = 0; item < AnimParams[slot].sound_count; ++item) {
                    EdFileRead(AnimParams[slot].sound_names[item], 16);
                    AnimParams[slot].sound_ids[item] = -1;
                    AnimParams[slot].sound_flags[item] = EdFileReadInt();
                    AnimParams[slot].sound_values[item] = EdFileReadFloat();
                    EdFileReadNuVec(&AnimParams[slot].sound_positions[item]);
                }
            }
            for (item = 0; item < extra; ++item) {
                EdFileRead(discarded_name, 16);
                EdFileReadInt();
                EdFileReadFloat();
                EdFileReadNuVec(&discarded_position);
            }
            NuGScnGetSpecial(&special, scene, AnimParams[slot].instance_id);
            instance = NuSpecialGetInstanceix(&special);
            AnimParams[slot].platform_id = -1;
            terrain = CurrentTerrain;
            if (instance != -1) {
                for (item = 0; item < terrain->max_platforms; ++item) {
                    platform = &terrain->platforms[item];
                    if (platform->scene_object != NULL && platform->scene_object_index == instance) {
                        AnimParams[slot].platform_id = item;
                        break;
                    }
                }
            }
            if (version >= 4) {
                AnimParams[slot].bounce_impulse = EdFileReadFloat();
                AnimParams[slot].bounce_spring = EdFileReadFloat();
                AnimParams[slot].bounce_damping = EdFileReadFloat();
            } else {
                AnimParams[slot].bounce_impulse = 0;
                AnimParams[slot].bounce_spring = 0;
                AnimParams[slot].bounce_damping = 0;
            }
            /* PlatInstBounce(platform_id, impulse, spring, damping), expanded in place: the arguments are
               copied first and CurrentTerrain is re-read for every store. */
            if (AnimParams[slot].platform_id != -1) {
                item = AnimParams[slot].platform_id;
                impulse = AnimParams[slot].bounce_impulse;
                spring = AnimParams[slot].bounce_spring;
                damping = AnimParams[slot].bounce_damping;
                if (item >= 0 && item < CurrentTerrain->max_platforms) {
                    if (CurrentTerrain->platforms[item].bounce_impulse == 0.0f) {
                        CurrentTerrain->platforms[item].bounce_offset = 0.0f;
                        CurrentTerrain->platforms[item].bounce_velocity = 0.0f;
                    }
                    CurrentTerrain->platforms[item].bounce_impulse = impulse;
                    CurrentTerrain->platforms[item].bounce_spring = spring;
                    CurrentTerrain->platforms[item].bounce_damping = damping;
                }
            }
            AnimParams[slot].page = (i8)page;
            ++edanim_params_used;
        }
        EdFileSetReadWrongEndianess(0);
        EdFileClose();
        edanim_page_used[page] = 1;
        edanim_page_scene[page] = scene;
        edbits_anim_page = page;
        edanim_next_param = slot;
        edanim_particle_mode = 0;
        edanim_nearest = -1;
        edanim_nearest_param_id = -1;
        edanimDetermineNearestAnim(1.0f);
        return page;
    }

    NUMTL *edanim_mtl_zoff = 0;
    NUMTL *edanim_mtl = 0;

    void edanimDrawCursor(void) {
        NURND_VERTEX3D line[2];
        NUVEC direction;
        nuhspecial_s special;
        line[0].colour = 0xffffffff;
        line[1].colour = 0xffffffff;
        line[0].position.x = edanim_cam_pos.x - 0.5f;
        line[0].position.y = edanim_cam_pos.y;
        line[0].position.z = edanim_cam_pos.z;
        line[1].position.x = edanim_cam_pos.x + 0.5f;
        line[1].position.y = edanim_cam_pos.y;
        line[1].position.z = edanim_cam_pos.z;
        NuRndrLine3d(line, edanim_mtl, NULL);
        line[0].colour = 0xffffffff;
        line[1].colour = 0xffffffff;
        line[0].position.x = edanim_cam_pos.x;
        line[0].position.y = edanim_cam_pos.y - 0.5f;
        line[0].position.z = edanim_cam_pos.z;
        line[1].position.x = edanim_cam_pos.x;
        line[1].position.y = edanim_cam_pos.y + 0.5f;
        line[1].position.z = edanim_cam_pos.z;
        NuRndrLine3d(line, edanim_mtl, NULL);
        line[0].colour = 0xffffffff;
        line[1].colour = 0xffffffff;
        line[0].position.x = edanim_cam_pos.x;
        line[0].position.y = edanim_cam_pos.y;
        line[0].position.z = edanim_cam_pos.z - 0.5f;
        line[1].position.x = edanim_cam_pos.x;
        line[1].position.y = edanim_cam_pos.y;
        line[1].position.z = edanim_cam_pos.z + 0.5f;
        NuRndrLine3d(line, edanim_mtl, NULL);
        if (edanim_particle_mode) {
            direction.x = 0.0f;
            direction.y = 0.375f;
            direction.z = 0.0f;
            NuVecRotateZ(&direction, &direction, edanim_emitrotz);
            NuVecRotateY(&direction, &direction, edanim_emitroty);
            line[0].colour = 0xff0000ff;
            line[1].colour = 0xff0000ff;
            line[0].position.x = edanim_cam_pos.x;
            line[0].position.y = edanim_cam_pos.y;
            line[0].position.z = edanim_cam_pos.z;
            line[1].position.x = edanim_cam_pos.x + direction.x;
            line[1].position.y = edanim_cam_pos.y + direction.y;
            line[1].position.z = edanim_cam_pos.z + direction.z;
            NuRndrLine3d(line, edanim_mtl, NULL);
        }
        NuRndrRect2di(0x1720, 0xa50, 0xdc0, 0x370, 0x80808080, edanim_mtl_zoff);
        NuRndrRect2di(0x1710, 0x990, 0xde0, 0xc0, 0x80000000, edanim_mtl_zoff);
        NuRndrLine2di(0x1710, 0xa50, 0x1710, 0xdc8, 0x80000000, edanim_mtl_zoff);
        NuRndrLine2di(0x24f0, 0xa50, 0x24f0, 0xdc8, 0x80000000, edanim_mtl_zoff);
        NuRndrLine2di(0x1710, 0xdc8, 0x24f0, 0xdc8, 0x80000000, edanim_mtl_zoff);
        NuQFntPushPrintMode(NUQFNT_MODE_2D);
        NuQFntPushCoordinateSystem(NUQFNT_CSMODE_PS2);
        NuQFntSet(system_qfont);
        NuQFntSetColour(system_qfont, 0xe0e0e0e0);
        NuQFntPrintEx(system_qfont, 0x17c0, 0xa28, 0x10, "Info Box");
        NuQFntSetColour(system_qfont, 0x80000000);
        if (edanim_nearest == -1) {
            NuQFntPrintEx(system_qfont, 0x17c0, 0xaf0, 0x10, "Curr Spcl: <none>");
        } else {
            NuGScnGetSpecial(&special, edbits_base_scene, edanim_nearest);
            NuQFntPrintEx(system_qfont, 0x17c0, 0xaf0, 0x10, "Curr Spcl: %s", NuSpecialGetName(&special));
        }
        if (edanim_nearest_param_id == -1) {
            NuQFntPrintEx(system_qfont, 0x17c0, 0xb90, 0x10, "Params: No");
        } else {
            NuQFntPrintEx(system_qfont, 0x17c0, 0xb90, 0x10, "Params: Yes");
            if (edanim_particle_mode) {
                NuQFntPrintEx(system_qfont, 0x1810, 0xc30, 0x10, "Particles: %d (Max %d)", AnimParams[edanim_nearest_param_id].effect_count,
                              8);
                if (edanim_particle_type == -1) {
                    NuQFntPrintEx(system_qfont, 0x1810, 0xcd0, 0x10, "Select Type: <none>");
                } else {
                    NuQFntPrintEx(system_qfont, 0x1810, 0xcd0, 0x10, "Select Type: %s", debtab[edanim_particle_type]->name);
                }
            } else if (edanim_sound_mode) {
                NuQFntPrintEx(system_qfont, 0x1810, 0xc30, 0x10, "Sounds: %d (Max %d)", AnimParams[edanim_nearest_param_id].sound_count, 8);
                if (edanim_sound_type == -1) {
                    NuQFntPrintEx(system_qfont, 0x1810, 0xcd0, 0x10, "Select Type: <none>");
                } else {
                    NuQFntPrintEx(system_qfont, 0x1810, 0xcd0, 0x10, "Select Type: %s", NULL);
                }
            }
        }
        NuQFntPrintEx(system_qfont, 0x17c0, 0xd70, 0x10, "%5.2f", edanim_cam_pos.x);
        NuQFntPrintEx(system_qfont, 0x1c20, 0xd70, 0x10, "%5.2f", edanim_cam_pos.y);
        NuQFntPrintEx(system_qfont, 0x2080, 0xd70, 0x10, "%5.2f", edanim_cam_pos.z);
        NuQFntPopPrintMode();
        NuQFntPopCoordinateSystem();
    }

