    i32 edanimProc(f32 delta_time, FRAME_PAD *pad) {
        if (edanim_active_menu) {
            eduiMenuProcess(edanim_active_menu, delta_time, pad);
            return 0;
        }
        edanimDoInput(pad);
        if (edanim_particle_mode) {
            edanimDetermineNearestParticle(1.0f);
        } else if (edanim_sound_mode) {
            edanimDetermineNearestSound(1.0f);
        } else {
            edanimDetermineNearestAnim(1.0f);
        }
        if (pad->digital_buttons_pressed & PAD_BUTTON_START) {
            edanim_particle_mode = 0;
            return 1;
        }
        return 0;
    }

    void edanimRenderParticleEmitters(i32 parameter_index) {
        nuhspecial_s special;
        NUVEC *base_position;
        i32 particle;
        i32 colour;
        NuGScnGetSpecial(&special, edbits_base_scene, AnimParams[parameter_index].instance_id);
        base_position = NuSpecialGetPos(&special);
        for (particle = 0; particle < AnimParams[parameter_index].effect_count; ++particle) {
            if (AnimParams[parameter_index].effect_ids[particle] == -1) {
                continue;
            }
            if (edanim_particle_mode && edanim_nearest_particle == particle) {
                DEBRIS_INFO *definition = debtab[AnimParams[parameter_index].effect_ids[particle]];
                if (definition->generator_type == DEBRIS_GENERATOR_NORMAL) {
                    edbitsDrawCube(base_position->x + AnimParams[parameter_index].effect_positions[particle][0],
                                   base_position->y + AnimParams[parameter_index].effect_positions[particle][1],
                                   base_position->z + AnimParams[parameter_index].effect_positions[particle][2],
                                   definition->emitter_random_extent.x, definition->emitter_random_extent.y,
                                   definition->emitter_random_extent.z, edanim_emitrotz, edanim_emitroty, 0, 0, 0, 0xff008000, edanim_mtl);
                }
                colour = 0xff00ff00;
            } else {
                colour = 0xffffffff;
            }
            edbitsDrawDiagonalCross(base_position->x + AnimParams[parameter_index].effect_positions[particle][0],
                                    base_position->y + AnimParams[parameter_index].effect_positions[particle][1],
                                    base_position->z + AnimParams[parameter_index].effect_positions[particle][2], 0.25f, colour,
                                    edanim_mtl);
        }
    }

    void edanimRenderSoundEmitters(i32 parameter_index) {
        nuhspecial_s special;
        NUVEC *base_position;
        i32 sound;
        i32 colour;
        NuGScnGetSpecial(&special, edbits_base_scene, AnimParams[parameter_index].instance_id);
        base_position = NuSpecialGetPos(&special);
        for (sound = 0; sound < AnimParams[parameter_index].sound_count; ++sound) {
            if (AnimParams[parameter_index].sound_flags[sound] == -1) {
                continue;
            }
            colour = edanim_sound_mode && edanim_nearest_sound == sound ? 0xffff0000 : 0xffffffff;
            edbitsDrawDiagonalCross(base_position->x + AnimParams[parameter_index].sound_positions[sound].x,
                                    base_position->y + AnimParams[parameter_index].sound_positions[sound].y,
                                    base_position->z + AnimParams[parameter_index].sound_positions[sound].z, 0.25f, colour, edanim_mtl);
        }
    }

    void edanimRender(void) {
        if (edbitsProcessCubemapDump()) {
            return;
        }
        edcamSet();
        edanimDrawCursor();

        if (edanim_nearest != -1) {
            nuhspecial_s special;
            struct nuvec_s *position;
            i32 colour;
            if (edanim_particle_mode) {
                colour = 0xff00ff00;
            } else if (edanim_sound_mode) {
                colour = 0xffff0000;
            } else {
                colour = edanim_nearest_param_id != -1 ? 0xffffffff : 0xff808080;
            }

            NuGScnGetSpecial(&special, edbits_base_scene, edanim_nearest);
            position = NuSpecialGetPos(&special);
            edbitsDrawCube(position->x, position->y, position->z, 0.5f, 0.5f, 0.5f, 0, 0, 0, 0, 0, colour, edanim_mtl);

            if (edanim_particle_mode) {
                edanimRenderParticleEmitters(edanim_nearest_param_id);
            }
            if (edanim_sound_mode) {
                edanimRenderSoundEmitters(edanim_nearest_param_id);
            }
        }

        if (edanim_active_menu) {
            eduiMenuRender(edanim_active_menu);
        }
    }

    i32 edbriLoadPage(char *path, void *scene) {
        i32 page = -1;
        i32 count;
        i32 index;
        i32 i;
        char name[20];
        i = 0;
        do {
            if (!edbri_page_used[i]) {
                page = i;
                break;
            }
            i++;
        } while (i < 8);
        if (page == -1) {
            return -1;
        }
        EdFileSetMedia(1);
        if (!EdFileOpen(path, 0)) {
            return -1;
        }
        if (EdFileReadInt() > 1) {
            EdFileClose();
            return -1;
        }
        count = EdFileReadInt();
        if (edbri_bridges_used + count > 64) {
            count = 64 - edbri_bridges_used;
        }
        index = 0;
        for (i = 0; i < count; i++) {
            /* Tests the record before checking the index limit. */
            while (edBridges[index].connection_index != -1 && index < 64) {
                ++index;
            }
            if (index < 64) {
                edBridges[index].instance_id = -1;
                EdFileReadNuVec(&edBridges[index].position);
                edBridges[index].length = EdFileReadFloat();
                edBridges[index].width = EdFileReadFloat();
                edBridges[index].rotation_z = EdFileReadShort();
                edBridges[index].rotation_y = EdFileReadShort();
                edBridges[index].connection_index = page;
                edBridges[index].plank_count = EdFileReadChar();
                edBridges[index].post_interval = EdFileReadChar();
                EdFileRead(name, sizeof(name));
                if (name[0] == '\0') {
                    edBridges[index].special_20 = -1;
                } else {
                    edBridges[index].special_20 = edbitsLookupInstance(name, (NUGSCN *)scene);
                }
                EdFileRead(name, sizeof(name));
                if (name[0] == '\0') {
                    edBridges[index].special_24 = -1;
                } else {
                    edBridges[index].special_24 = edbitsLookupInstance(name, (NUGSCN *)scene);
                }
                edBridges[index].tension = EdFileReadFloat();
                edBridges[index].damping = EdFileReadFloat();
                edBridges[index].gravity = EdFileReadFloat();
                edBridges[index].player_weight = EdFileReadFloat();
                edBridges[index].rope_height = EdFileReadFloat();
                edBridges[index].stability = EdFileReadFloat();
                edBridges[index].red = (u8)EdFileReadChar();
                edBridges[index].green = (u8)EdFileReadChar();
                edBridges[index].blue = (u8)EdFileReadChar();
                edBridges[index].alpha = (u8)EdFileReadChar();
                ++edbri_bridges_used;
            }
        }
        EdFileClose();
        edbri_nearest = -1;
        edbriDetermineNearest(1.0f);
        edbri_page_used[page] = 1;
        edbri_page_scene[page] = (NUGSCN_s *)scene;
        return page;
    }

    void edbriStartPage(i32 page_number) {
        i8 page = (i8)page_number;
        i32 index;
        if (edbri_page_used[page] && edbri_page_scene[page]) {
            for (index = 0; index < 64; ++index) {
                if (edBridges[index].connection_index == page) {
                    edbriBridgeUpdate(index, edbri_page_scene[page]);
                }
            }
        }
    }

    void edbriStartUsedPages(void) {
        i32 page;
        for (page = 0; page < 8; ++page) {
            if (edbri_page_used[page]) {
                edbriStartPage(page);
            }
        }
    }

