    i32 edgra_page_vectors_valid[8] = {0};
    void *edgra_page_terrain[8] = {0};
    i32 edgra_page_calculate_done[8] = {0};

    void edgraStartPage(i8 page) {
        i32 i;
        void *saved_terrain;
        if (!edgra_page_used[page] || !edgra_page_scene[page] || edgra_page_on[page]) {
            return;
        }
        saved_terrain = PCGrassTerrainScene;
        PCGrassTerrainScene = (TERRAIN_SET *)edgra_page_terrain[page];
        if (!edgra_page_calculate_done[page]) {
            if (edgra_page_vectors_valid[page] == 0) {
                edgraCalculatePage(page, 1);
                edgra_page_vectors_valid[page] = 1;
            } else {
                edgraCalculatePage(page, 0);
            }
            edgra_page_calculate_done[page] = 1;
        }
        for (i = 0; i < EDGRA_MAX_CLUMPS; ++i) {
            if (GrassClumps[i].element_count && GrassClumps[i].page == (u8)page) {
                i32 count = GrassClumps[i].element_count;
                if (edgra_units_used + count > 0x3000) {
                    count = 0x3000 - edgra_units_used;
                }
                if (count > 0) {
                    NUGSCN *scene = edgra_page_scene[page];
                    nuhspecial_s special;
                    special.scene = scene;
                    if (scene->display_list == NULL) {
                        special.special = (NUMTX *)&scene->specials[GrassClumps[i].special_index];
                        special.display_special = NULL;
                    } else {
                        special.special = NULL;
                        special.display_special = &scene->display_list->specials[GrassClumps[i].special_index];
                    }
                    if (GrassClumps[i].kind == 2 || GrassClumps[i].kind == 3) {
                        NuFadeObjCreateMtx(&special, GrassClumps[i].matrices, (i16)count, GrassClumps[i].near_distance,
                                           GrassClumps[i].far_distance, GrassClumps[i].flags);
                    } else {
                        NuWindCreateMtx(&special, GrassClumps[i].matrices, (i16)count, GrassClumps[i].wind, GrassClumps[i].bend_height,
                                        GrassClumps[i].flags, GrassClumps[i].near_distance, GrassClumps[i].far_distance);
                    }
                    edgra_units_used += count;
                }
            }
        }
        edgra_page_on[page] = 1;
        PCGrassTerrainScene = (TERRAIN_SET *)saved_terrain;
    }

    void edgraStopPage(i8 page) {
        i32 i;
        if (edgra_page_on[page]) {
            edgra_page_on[page] = 0;
            edgra_units_used = 0;
            NuWindInit();
            NuFadeObjInit();
            for (i = 0; i < 8; ++i) {
                if (edgra_page_on[i]) {
                    edgra_page_on[i] = 0;
                    edgraStartPage((i8)i);
                }
            }
        }
    }

    void edgraClearPage(i8 page) {
        i32 i;
        edgraStopPage(page);
        for (i = 0; i < EDGRA_MAX_CLUMPS; ++i) {
            if (GrassClumps[i].element_count && GrassClumps[i].page == (u8)page) {
                if (GrassClumps[i].kind == 3) {
                    IndGrassClumpsUsed[GrassClumps[i].individual_index] = 0;
                    --edgra_ind_clumps_used;
                }
                GrassClumps[i].element_count = 0;
                --edgra_clumps_used;
            }
        }
        edgra_page_used[page] = 0;
        edgra_page_scene[page] = NULL;
        edgra_page_matrix_stack[page] = NULL;
        edgra_page_vectors_valid[page] = 0;
        edgra_page_calculate_done[page] = 0;
    }

    void edgraInitAllClumps(void) {
        i32 page;
        edgra_units_used = 0;
        NuWindInit();
        NuFadeObjInit();
        for (page = 0; page < 8; ++page) {
            edgra_page_on[page] = 0;
        }
        for (page = 0; page < 8; ++page) {
            if (edgra_page_used[page]) {
                edgra_page_calculate_done[page] = 0;
                edgra_page_vectors_valid[page] = 0;
                edgraStartPage((i8)page);
            }
        }
    }

