    void edgraClumpPlace(i32 index, NUVEC *position) {
        GrassClumps[index].position = *position;
        GrassClumps[index].size = edgra_size;
        GrassClumps[index].rotation_z = (i16)edgra_rotz;
        GrassClumps[index].rotation_y = (i16)edgra_roty;
        if (edgra_mode != 3) {
            if (edgra_units_used + edgra_clump_size - GrassClumps[index].element_count <= 0x3000) {
                GrassClumps[index].element_count = edgra_clump_size;
            }
        }
        edgra_free_vecbuffer = GrassClumps[index].vector_buffer + GrassClumps[index].element_count;
        edgraInitAllClumps();
    }

    void edgraInstancePlace(i32 index, NUVEC *position) {
        GetIndGrassClump(GrassClumps[edgra_nearest].individual_index, index)->position.x =
            position->x - GrassClumps[edgra_nearest].position.x;
        GetIndGrassClump(GrassClumps[edgra_nearest].individual_index, index)->position.y =
            position->y - GrassClumps[edgra_nearest].position.y;
        GetIndGrassClump(GrassClumps[edgra_nearest].individual_index, index)->position.z =
            position->z - GrassClumps[edgra_nearest].position.z;
        GetIndGrassClump(GrassClumps[edgra_nearest].individual_index, index)->scale = 1.0f;
        GetIndGrassClump(GrassClumps[edgra_nearest].individual_index, index)->rotation_z = (i16)edgra_rotz;
        GetIndGrassClump(GrassClumps[edgra_nearest].individual_index, index)->rotation_y = (i16)edgra_roty;
        edgraInitAllClumps();
    }

    void edgraClumpReseed(i32 index) {
        GrassClumps[index].seed = NuRand(NULL);
        edgraInitAllClumps();
    }

    i32 edgra_last_clump_in_buffer = -1;
    i32 edgra_pageid = 0;

    i32 edgraClumpCreate(NUVEC *position) {
        i32 index = 0;
        i32 individual = 0;
        if (edgra_clumps_used == EDGRA_MAX_CLUMPS) {
            return -1;
        }
        if (edgra_copy_source == -1 && edgra_mode == 3) {
            if (edgra_units_used == 0x3000 || edgra_ind_clumps_used == EDGRA_MAX_INDIVIDUAL_CLUMPS) {
                return -1;
            }
        } else if (edgra_units_used + edgra_clump_size > 0x3000) {
            return -1;
        }
        while (GrassClumps[index].element_count != 0) {
            ++index;
        }
        if (edgra_copy_source != -1) {
            GrassClumps[index].special_index = GrassClumps[edgra_copy_source].special_index;
            GrassClumps[index].element_count = edgra_clump_size;
            GrassClumps[index].wind = GrassClumps[edgra_copy_source].wind;
            GrassClumps[index].flags = GrassClumps[edgra_copy_source].flags;
            GrassClumps[index].bend_height = GrassClumps[edgra_copy_source].bend_height;
            GrassClumps[index].page = (u8)edgra_pageid;
            GrassClumps[index].seed = NuRand(NULL);
            GrassClumps[index].area_shape = GrassClumps[edgra_copy_source].area_shape;
            GrassClumps[index].distribution = GrassClumps[edgra_copy_source].distribution;
            GrassClumps[index].kind = GrassClumps[edgra_copy_source].kind;
            GrassClumps[index].min_model_size = GrassClumps[edgra_copy_source].min_model_size;
            GrassClumps[index].max_model_size = GrassClumps[edgra_copy_source].max_model_size;
            GrassClumps[index].near_distance = GrassClumps[edgra_copy_source].near_distance;
            GrassClumps[index].far_distance = GrassClumps[edgra_copy_source].far_distance;
            GrassClumps[index].follow_terrain = GrassClumps[edgra_copy_source].follow_terrain;
            GrassClumps[index].terrain_offset = GrassClumps[edgra_copy_source].terrain_offset;
            GrassClumps[index].follow_slope = GrassClumps[edgra_copy_source].follow_slope;
        } else {
            GrassClumps[index].special_index = edgra_instance_type;
            if (edgra_mode == 3) {
                GrassClumps[index].element_count = 1;
            } else {
                GrassClumps[index].element_count = edgra_clump_size;
            }
            GrassClumps[index].wind = 0.2f;
            GrassClumps[index].flags = 1;
            GrassClumps[index].bend_height = 1.0f;
            GrassClumps[index].page = (u8)edgra_pageid;
            GrassClumps[index].seed = NuRand(NULL);
            GrassClumps[index].area_shape = 1;
            GrassClumps[index].distribution = 1;
            GrassClumps[index].kind = (u8)edgra_mode;
            GrassClumps[index].min_model_size = 0.0f;
            GrassClumps[index].max_model_size = 1.0f;
            GrassClumps[index].near_distance = edgra_global_fadein;
            GrassClumps[index].far_distance = edgra_global_fadeout;
            GrassClumps[index].follow_terrain = 1;
            GrassClumps[index].terrain_offset = 0.0f;
            GrassClumps[index].follow_slope = 1;
        }
        if (GrassClumps[index].kind == 3) {
            while (IndGrassClumpsUsed[individual]) {
                ++individual;
            }
            GrassClumps[index].individual_index = (i16)individual;
            IndGrassClumpsUsed[individual] = 1;
            GetIndGrassClump(individual, 0)->position.x = 0.0f;
            GetIndGrassClump(individual, 0)->position.y = 0.0f;
            GetIndGrassClump(individual, 0)->position.z = 0.0f;
            GetIndGrassClump(individual, 0)->scale = 1.0f;
            GetIndGrassClump(individual, 0)->rotation_z = (i16)edgra_rotz;
            GetIndGrassClump(individual, 0)->rotation_y = (i16)edgra_roty;
            ++edgra_ind_clumps_used;
        } else {
            GrassClumps[index].individual_index = -1;
        }
        ++edgra_clumps_used;
        if (!edgra_page_used[edgra_pageid]) {
            edgra_page_used[edgra_pageid] = 1;
            edgra_page_scene[edgra_pageid] = edbits_base_scene;
            edgra_page_terrain[edgra_pageid] = edbits_base_terrain;
            edgra_page_matrix_stack[edgra_pageid] = edgra_mtxbuffer;
        }
        GrassClumps[index].vector_buffer = (NUVEC *)edgra_free_vecbuffer;
        edgra_last_clump_in_buffer = index;
        edgraClumpPlace(index, position);
        return index;
    }

    void edgraInstanceCreate(NUVEC *position) {
        i32 index;
        if (edgra_nearest != -1 && GrassClumps[edgra_nearest].element_count != EDGRA_MAX_UNITS_PER_INDIVIDUAL_CLUMP) {
            index = GrassClumps[edgra_nearest].element_count++;
            edgraInstancePlace(index, position);
        }
    }

    void edgraClumpDestroy(i32 index) {
        GrassClumps[index].element_count = 0;
        edgra_free_vecbuffer = GrassClumps[index].vector_buffer;
        GrassClumps[index].vector_buffer = NULL;
        --edgra_clumps_used;
        if (GrassClumps[index].kind == 3) {
            IndGrassClumpsUsed[GrassClumps[index].individual_index] = 0;
            --edgra_ind_clumps_used;
        }
        edgraInitAllClumps();
    }

    void edgraInstanceDestroy(i32 index) {
        i32 i;
        if (edgra_nearest != -1 && GrassClumps[edgra_nearest].element_count != 1) {
            if (index != GrassClumps[edgra_nearest].element_count - 1) {
                for (i = index; i < GrassClumps[edgra_nearest].element_count - 1; ++i) {
                    (&IndGrassClumps[EDGRA_MAX_UNITS_PER_INDIVIDUAL_CLUMP * (GrassClumps[edgra_nearest].individual_index) + i])->position =
                        (&IndGrassClumps[EDGRA_MAX_UNITS_PER_INDIVIDUAL_CLUMP * (GrassClumps[edgra_nearest].individual_index) + (i + 1)])
                            ->position;
                    (&IndGrassClumps[EDGRA_MAX_UNITS_PER_INDIVIDUAL_CLUMP * (GrassClumps[edgra_nearest].individual_index) + i])->scale =
                        (&IndGrassClumps[EDGRA_MAX_UNITS_PER_INDIVIDUAL_CLUMP * (GrassClumps[edgra_nearest].individual_index) + (i + 1)])
                            ->scale;
                    (&IndGrassClumps[EDGRA_MAX_UNITS_PER_INDIVIDUAL_CLUMP * (GrassClumps[edgra_nearest].individual_index) + i])
                        ->rotation_z =
                        (&IndGrassClumps[EDGRA_MAX_UNITS_PER_INDIVIDUAL_CLUMP * (GrassClumps[edgra_nearest].individual_index) + (i + 1)])
                            ->rotation_z;
                    (&IndGrassClumps[EDGRA_MAX_UNITS_PER_INDIVIDUAL_CLUMP * (GrassClumps[edgra_nearest].individual_index) + i])
                        ->rotation_y =
                        (&IndGrassClumps[EDGRA_MAX_UNITS_PER_INDIVIDUAL_CLUMP * (GrassClumps[edgra_nearest].individual_index) + (i + 1)])
                            ->rotation_y;
                }
            }
            --GrassClumps[edgra_nearest].element_count;
            edgraInitAllClumps();
        }
    }

    void edgracbApplyGlobalFade(eduimenu_s *menu, eduiitem_s *unused1, u32 unused2) {
        i32 i;
        struct eduimenu_s *parent = NULL;
        for (i = 0; i < EDGRA_MAX_CLUMPS; ++i) {
            if (GrassClumps[i].element_count) {
                GrassClumps[i].near_distance = edgra_global_fadein;
                GrassClumps[i].far_distance = edgra_global_fadeout;
            }
        }
        edgraInitAllClumps();
        if (menu->parent) {
            parent = menu->parent;
            eduiMenuDetach(menu);
        }
        if (menu->callback) {
            menu->callback(menu, parent);
        }
    }

