    void cbPtlTypeMenu(eduimenu_s *parent, eduiitem_s *unused1, u32 unused2) {
        i32 count = 0;
        i32 found_selected;
        i32 index;
        char title[32];
        for (index = 1; index < debinf_count; ++index) {
            if (debtab[index] == NULL) {
                continue;
            }
            if (edpp_effect_list == 1) {
                if (debtab[index]->category == edpp_effect_list && debtab[index]->page == edbits_particle_level_page) {
                    ++count;
                }
            } else if (debtab[index]->category == edpp_effect_list) {
                ++count;
            }
        }
        sprintf(title, "Particle Types (%d)", count);
        ptltypemenu = eduiMenuCreate(70, 70, 180, 250, ed_fnt, cbPtlCancelTypeMenu, title);
        if (ptltypemenu == NULL) {
            return;
        }
        found_selected = 0;
        for (index = 1; index < debinf_count; ++index) {
            i32 placed;
            i32 selected;
            i32 i;
            if (debtab[index] == NULL) {
                continue;
            }
            if (edpp_effect_list == 1) {
                if (debtab[index]->category != edpp_effect_list) {
                    continue;
                }
                if (debtab[index]->page != edbits_particle_level_page) {
                    continue;
                }
            } else if (debtab[index]->category != edpp_effect_list) {
                continue;
            }
            placed = 0;
            for (i = 0; i < 512; ++i) {
                if (edpp_ptls[i].instance_id != -1 && edpp_ptls[i].instance_id != EDPP_SHELVED && edpp_ptls[i].effect_index == index) {
                    placed = 1;
                    break;
                }
            }
            selected = edpp_create_type == index;
            if (placed) {
                eduiMenuAddItem(ptltypemenu, eduiItemCheckCreate(index, edblack, selected, 1, cbPtlSelType, debtab[index]->name));
            } else {
                eduiMenuAddItem(ptltypemenu, eduiItemCheckCreate(index, eddarkred, selected, 1, cbPtlSelType, debtab[index]->name));
            }
            if (selected == 1) {
                ptltypemenu->selected = edui_last_item;
                found_selected = 1;
            }
        }
        eduiMenuSortItemsByTxt(ptltypemenu);
        eduiMenuAddItemFirst(ptltypemenu, eduiItemSelCreate(1, edblack, 0, 0, cbPtlAddEffect, "Add Effect"));
        eduiMenuAttach(parent, ptltypemenu);
        ptltypemenu->x = parent->x + 10;
        ptltypemenu->y = parent->y + 40;
        if (found_selected) {
            ptltypemenu->first_visible = ptltypemenu->selected;
        }
    }

